// 영화굿즈 캘린더 — 서버 수집기 (GitHub Actions에서 15분마다 실행)
// 확장 프로그램과 같은 수집·예측 코드(lib/*.js)를 Node에서 실행해 site/data.json을 만든다.
// 실행: TZ=Asia/Seoul node scraper/run.mjs [--only=LOTTE,MEGABOX] [--state=state/state.json]
import fs from 'node:fs';
import path from 'node:path';
import vm from 'node:vm';
import { fileURLToPath } from 'node:url';

const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const args = Object.fromEntries(process.argv.slice(2).map((a) => { const [k, v] = a.replace(/^--/, '').split('='); return [k, v ?? true]; }));
const STATE = path.resolve(ROOT, args.state || 'state/state.json');
const OUT = path.resolve(ROOT, args.out || 'site/data.json');
const ONLY = args.only ? String(args.only).split(',') : null;

// ── lib 로드 (브라우저용 IIFE들이 globalThis.GC 에 붙음)
globalThis.self = globalThis;
for (const f of ['adapters.js', 'predict.js', 'showtimes.js']) vm.runInThisContext(fs.readFileSync(path.join(ROOT, 'lib', f), 'utf8'), { filename: f });
const GC = globalThis.GC;

// ── HTTP
const UA = 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/141.0 Safari/537.36';
const REFERER = {
  'cgv.co.kr': 'https://cgv.co.kr/evt/giveawayState',
  'www.megabox.co.kr': 'https://www.megabox.co.kr/event/movie',
  'www.lottecinema.co.kr': 'https://www.lottecinema.co.kr/NLCHS/Event/DetailList?code=20',
  'www.cineq.co.kr': 'https://www.cineq.co.kr/Event/List',
  'www.cinecube.co.kr': 'https://www.cinecube.co.kr/event/EG001',
  'www.dtryx.com': 'https://www.dtryx.com/cinema/list.do',
  'www.laikacinema.com': 'https://www.laikacinema.com/event'
};
class RateLimit extends Error { constructor(m) { super(m); this.rateLimited = true; } }
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
const stats = {};
const hostFails = {};   // 연속 접속 실패 수 — 3번 연속이면 그 사이트는 이번 실행에서 건너뜀(시간초과로 전체가 멈추지 않게)
function blocked(host, why) { const e = new RateLimit(`${host} 접속 불가(${why}) — 해외 서버 차단 추정`); e.hostDown = true; return e; }
async function http(url, init = {}) {
  const u = new URL(url);
  if ((hostFails[u.host] || 0) >= 3) throw blocked(u.host, '연속 실패');
  const headers = Object.assign({ 'User-Agent': UA, 'Accept': 'application/json, text/plain, */*', 'Accept-Language': 'ko-KR,ko;q=0.9', Referer: REFERER[u.host] || u.origin + '/' }, init.method === 'POST' ? { Origin: u.origin } : {}, init.headers || {});
  const s = stats[u.host] || (stats[u.host] = { ok: 0, err: 0, codes: {} });
  let lastErr;
  for (let attempt = 0; attempt < 2; attempt++) {
    try {
      const ctrl = new AbortController(); const to = setTimeout(() => ctrl.abort(), 12000);
      const r = await fetch(url, Object.assign({}, init, { headers, signal: ctrl.signal }));
      clearTimeout(to);
      s.codes[r.status] = (s.codes[r.status] || 0) + 1;
      if (r.status === 429) throw new RateLimit('429 요청 제한');
      if (r.status === 403) { hostFails[u.host] = (hostFails[u.host] || 0) + 1; throw blocked(u.host, 'HTTP 403'); }
      if (!r.ok) { const e = new Error('HTTP ' + r.status); e.status = r.status; throw e; }
      s.ok++; hostFails[u.host] = 0;
      return await r.text();
    } catch (e) {
      lastErr = e; s.err++;
      if (e.rateLimited || (e.status && e.status < 500)) throw e;
      hostFails[u.host] = (hostFails[u.host] || 0) + 1;
      if (hostFails[u.host] >= 3) throw blocked(u.host, (e.cause && e.cause.code) || e.name || '응답 없음');
      await sleep(1000);
    }
  }
  throw lastErr;
}

// ── 진단: node scraper/run.mjs --diag
if (args.diag) {
  const tryOne = async (label, url, headers) => {
    const t = Date.now();
    try {
      const ctrl = new AbortController(); const to = setTimeout(() => ctrl.abort(), 15000);
      const r = await fetch(url, { headers, signal: ctrl.signal }); clearTimeout(to);
      const body = await r.text();
      console.log(`[진단] ${label}: ${r.status} ${Date.now() - t}ms server=${r.headers.get('server')} cf=${r.headers.get('cf-ray') ? 'y' : 'n'} akamai=${r.headers.get('x-akamai-transformed') || ''} | ${body.slice(0, 160).replace(/\s+/g, ' ')}`);
    } catch (e) { console.log(`[진단] ${label}: 실패 ${Date.now() - t}ms ${e.name} ${(e.cause && (e.cause.code || e.cause.message)) || e.message}`); }
  };
  await tryOne('위치', 'https://ipinfo.io/json', {});
  const cgv = 'https://cgv.co.kr/api/v1/content/event/saprm/saprm/searchSaprmEvtListForPage?coCd=A420&startRow=0&listCount=3';
  await tryOne('CGV 기본', cgv, { 'User-Agent': UA, 'Accept': 'application/json, text/plain, */*', 'Accept-Language': 'ko-KR,ko;q=0.9', Referer: 'https://cgv.co.kr/evt/giveawayState' });
  await tryOne('CGV UA만', cgv, { 'User-Agent': UA });
  await tryOne('CGV 헤더없음', cgv, {});
  await tryOne('CGV 메인', 'https://cgv.co.kr/', { 'User-Agent': UA });
  await tryOne('디트릭스', 'https://www.dtryx.com/cinema/showseq_list.do?BrandCd=indieart&CinemaCd=000067&PlaySDT=' + GC.todayStr(), { 'User-Agent': UA });
  await tryOne('디트릭스 메인', 'https://www.dtryx.com/', { 'User-Agent': UA });
  await tryOne('라이카', 'https://www.laikacinema.com/event', { 'User-Agent': UA });
  process.exit(0);
}
const memo = new Map(); // 같은 실행 안에서 같은 GET 재사용(디트릭스 시간표 등)
const ctx = (cache) => ({
  cache, sleep,
  get: async (url) => { if (memo.has(url)) return memo.get(url); const t = await http(url); if (/showseq_list|searchMovScnInfo/.test(url)) memo.set(url, t); return t; },
  postJSON: (url, obj) => http(url, { method: 'POST', headers: { 'Content-Type': 'application/json;charset=UTF-8', 'X-Requested-With': 'XMLHttpRequest' }, body: JSON.stringify(obj) }),
  postForm: (url, fields) => { const fd = new FormData(); for (const [k, v] of Object.entries(fields)) fd.append(k, v); return http(url, { method: 'POST', body: fd }); },
  postFormUrl: (url, fields) => http(url, { method: 'POST', headers: { 'Content-Type': 'application/x-www-form-urlencoded; charset=UTF-8', 'X-Requested-With': 'XMLHttpRequest' }, body: new URLSearchParams(fields).toString() })
});

// ── 상태(이력·학습·캐시) 로드
let state = { events: {}, meta: {}, history: {}, learn: {}, cache: {} };
try { state = Object.assign(state, JSON.parse(fs.readFileSync(STATE, 'utf8'))); } catch (e) { console.log('새 상태로 시작'); }
const { events, meta, history } = state;
const cache = state.cache;

const SOURCES = [
  ['LOTTE', 'fetchLotte'], ['MEGABOX', 'fetchMegabox'], ['CGV', 'fetchCGV'],
  ['CINEQ', 'fetchCineQ'], ['CINECUBE', 'fetchCinecube'], ['DTRYX', 'fetchDtryx'], ['INDIE', 'fetchIndie']
];

function recordHistory(ev, t) {
  for (const s of ev.stock || []) {
    const k = GC.histKey(ev.id, s.goodsId, s.theater);
    const arr = history[k] || (history[k] = []);
    const last = arr[arr.length - 1];
    const cnt = s.count != null ? s.count : null;
    if (!last || last[1] !== s.level || last[2] !== cnt) { arr.push([t, s.level, cnt]); if (arr.length > 300) arr.splice(0, arr.length - 300); }
    else last[3] = t;
  }
}

// ── PC 연동(relay): 해외 서버가 막힌 CGV·디트릭스는 사용자 크롬 확장이 relay/relay.json 으로 보내준 데이터를 사용
const RELAY_CHAINS = ['CGV', 'DTRYX'];
let relay = null;
try {
  relay = JSON.parse(fs.readFileSync(path.join(ROOT, 'relay/relay.json'), 'utf8'));
  const age = (Date.now() - relay.updatedAt) / 60000;
  console.log(`[연동] PC 크롬에서 받은 데이터 ${age.toFixed(0)}분 전 · 이벤트 ${Object.keys(relay.events || {}).length}`);
  if (age > 50) { console.log('[연동] 50분이 지나 사용하지 않음'); relay = null; }
} catch (e) { console.log('[연동] relay/relay.json 없음'); }
if (!relay) for (const chain of RELAY_CHAINS) if (meta[chain]) delete meta[chain].via;
if (relay) {
  for (const chain of RELAY_CHAINS) {
    const rel = Object.values(relay.events || {}).filter((e) => e.chain === chain);
    const rm = (relay.meta || {})[chain] || {};
    if (!rel.length) continue;
    for (const id of Object.keys(events)) if (events[id].chain === chain) delete events[id];
    for (const ev of rel) { events[ev.id] = ev; recordHistory(ev, ev.updatedAt || relay.updatedAt); }
    meta[chain] = { lastOk: rm.lastOk || relay.updatedAt, count: rel.length, lastError: null, via: 'PC 연동' };
  }
}

const t0 = Date.now();
for (const [key, fn] of SOURCES) {
  if (ONLY && !ONLY.includes(key)) continue;
  if (relay && RELAY_CHAINS.includes(key) && meta[key] && meta[key].via) { console.log(`[${key}] PC 연동 데이터 사용`); continue; }
  const m = meta[key] || (meta[key] = {});
  if (m.backoffUntil && Date.now() < m.backoffUntil) { console.log(`[${key}] 요청 제한 대기 중`); continue; }
  const st = Date.now();
  try {
    const res = key === 'INDIE' ? await GC.fetchIndie(ctx(cache), GC.INDIE_DEFAULTS) : await GC[fn](ctx(cache), key === 'CGV' ? { delay: 1300 } : undefined);
    if (!res.events.length && res.errors.length) throw new Error(res.errors[0]);
    const t = Date.now();
    for (const id of Object.keys(events)) if (events[id].chain === key) delete events[id];
    for (const ev of res.events) { ev.updatedAt = t; events[ev.id] = ev; recordHistory(ev, t); }
    Object.assign(m, { lastOk: t, count: res.events.length, errors: res.errors.slice(0, 10), lastError: null, backoffCount: 0 });
    console.log(`[${key}] ${res.events.length}건 (${((t - st) / 1000).toFixed(1)}s)${res.errors.length ? ' 부분오류 ' + res.errors.length : ''}`);
  } catch (e) {
    Object.assign(m, { lastError: e.message || String(e), lastErrorAt: Date.now() });
    if (e.hostDown) { m.backoffUntil = Date.now() + 45 * 60000; }
    else if (e.rateLimited) { m.backoffCount = (m.backoffCount || 0) + 1; m.backoffUntil = Date.now() + Math.min(120, 20 * 2 ** (m.backoffCount - 1)) * 60000; }
    console.log(`[${key}] 실패: ${m.lastError}`);
  }
}

// ── 상영시간 미리 계산: 오늘(영업일)·내일, 굿즈 대상 지점만
const now = new Date();
const today = GC.todayStr(now);
const addDays = (ymd, n) => { const [y, mo, d] = ymd.split('-').map(Number); return GC.todayStr(new Date(y, mo - 1, d + n)); };
const dates = [today, addDays(today, 1)];
if (now.getHours() < 6) dates.unshift(addDays(today, -1));
const active = (ev, d) => ev.start && ev.start <= d && (ev.end || ev.start) >= d || (ev.openEnd && ev.start && ev.start <= d);
const showtimes = {};
const SCHED_GAP = { CGV: 1300, MEGABOX: 300, LOTTE: 250, CINEQ: 300, DTRYX: 150 };
if (!ONLY || ONLY.includes('SHOWTIMES')) {
  const jobs = new Map();
  for (const d of dates) {
    for (const ev of Object.values(events)) {
      if (!active(ev, d) || ev.type === '굿즈 판매') continue;
      for (const th of GC.eventTheaters(ev)) {
        if (th.level === 'out') continue;
        const k = `${th.chain}|${th.id}|${d}`;
        const j = jobs.get(k) || { th, d, evs: new Set() };
        j.evs.add(ev.id); jobs.set(k, j);
      }
    }
  }
  const byChain = {};
  for (const [k, j] of jobs) {
    if (relay && RELAY_CHAINS.includes(j.th.chain) && relay.showtimes && relay.showtimes[k]) { showtimes[k] = relay.showtimes[k]; continue; }
    (byChain[j.th.chain] || (byChain[j.th.chain] = [])).push([k, j]);
  }
  await Promise.all(Object.entries(byChain).map(async ([chain, list]) => {
    if (meta[chain === 'DTRYX' ? 'DTRYX' : chain]?.backoffUntil > Date.now()) return;
    for (const [k, j] of list) {
      try {
        const rows = await GC.fetchSchedule(ctx(cache), chain, { id: j.th.id, name: j.th.name, brand: j.th.brand }, j.d);
        // 이 지점에 걸린 이벤트들의 영화 회차만 저장(용량 절약)
        const evs = [...j.evs].map((id) => events[id]);
        showtimes[k] = rows.filter((r) => evs.some((ev) => GC.rowMatchesEvent(r, ev)))
          .map(({ start, end, hall, format, remain, total, movie, movieRaw, pkg, special, bookable, url, theater }) => ({ start, end, hall, format, remain, total, movie, movieRaw, pkg, special, bookable, url, theater }));
      } catch (e) {
        showtimes[k] = { error: e.hostDown ? '이 영화관 시간표는 지금 불러올 수 없어요' : (e.message || String(e)) };
        if (e.rateLimited) { for (const [k2] of list) if (!showtimes[k2]) showtimes[k2] = showtimes[k]; break; }
      }
      await sleep(SCHED_GAP[chain] || 300);
    }
  }));
  console.log(`[상영시간] ${Object.keys(showtimes).length}곳·일 (${dates.join(', ')})`);
}

// ── 학습·정리
state.learn = GC.learnFromHistory(history, events, state.learn);
const cutoff = Date.now() - 21 * 864e5;
for (const [k, arr] of Object.entries(history)) {
  const evId = k.split('|')[0]; const last = arr[arr.length - 1];
  if (!events[evId] && (last[3] || last[0]) < cutoff) delete history[k];
}
// 끝난 지 7일 지난 이벤트 제거
for (const [id, ev] of Object.entries(events)) if (ev.end && ev.end < addDays(today, -7)) delete events[id];

// ── 공개용 data.json (이력은 진행 중 이벤트의 최근 3일만)
const recent = Date.now() - 3 * 864e5;
const pubHistory = {};
for (const [k, arr] of Object.entries(history)) {
  const evId = k.split('|')[0];
  const ev = events[evId];
  if (!ev || (ev.end && ev.end < today)) continue;
  const pts = arr.filter((p) => (p[3] || p[0]) >= recent);
  if (pts.length) pubHistory[k] = pts;
}
const pubMeta = Object.fromEntries(Object.entries(meta).map(([k, v]) => [k, { lastOk: v.lastOk, count: v.count, lastError: v.lastError && RELAY_CHAINS.includes(k) && !v.via ? 'PC 연동 대기 중' : v.lastError, lastErrorAt: v.lastErrorAt, backoffUntil: RELAY_CHAINS.includes(k) ? null : v.backoffUntil, via: v.via || null }]));
const data = { generatedAt: Date.now(), dates, events, history: pubHistory, learn: state.learn, meta: pubMeta, showtimes, stats };
fs.mkdirSync(path.dirname(OUT), { recursive: true });
fs.writeFileSync(OUT, JSON.stringify(data));
fs.mkdirSync(path.dirname(STATE), { recursive: true });
fs.writeFileSync(STATE, JSON.stringify(state));
console.log(`완료 ${((Date.now() - t0) / 1000).toFixed(0)}s · 이벤트 ${Object.keys(events).length} · data.json ${(fs.statSync(OUT).size / 1024).toFixed(0)}KB`);
console.log('호스트별 응답:', JSON.stringify(stats));

lib/predict.js.text:
/* 소진 예측 엔진
 * 입력: 이벤트(현재 재고), 확장이 쌓아온 재고 스냅샷 이력(history), 종료된 굿즈들에서 학습한 통계(learn)
 * 방식(설명 가능한 통계 모델):
 *  1) 수량 공개(롯데): 지점별 최근 감소 속도(개/시간)를 가중 회귀로 추정 → 남은 수량 / 속도 = 소진 예상 시각
 *     이력이 부족하면 같은 굿즈 다른 지점들의 평균 속도(교차 지점), 그것도 없으면 학습된 체인 평균 속도를 사용
 *  2) 단계 공개(CGV·메가박스): 현재 단계에 진입한 시각 + "그 단계 → 소진" 소요시간 중앙값(학습값, 없으면 기본값)
 *     같은 굿즈의 서울 지점 중 이미 소진된 비율이 높을수록 남은 시간을 줄임(수요 신호)
 *  3) 예상 시각의 불확실성(σ)을 표본 수에 따라 두고, 오늘 영업 종료(24시) 전에 소진될 확률을 로지스틱으로 계산
 */
(function (G) {
  const GC = G.GC || (G.GC = {});
  const H = 3600 * 1000;

  // 학습값이 없을 때 쓰는 기본값(영업시간 기준 시간): 단계 진입 → 소진까지 중앙값
  const DEFAULT_LEVEL_TO_OUT = {
    CGV: { plenty: 30, some: 8, few: 2.5 },
    MEGABOX: { plenty: 30, some: 8, few: 3 },
    LOTTE: { plenty: 30, some: 10, few: 3 }
  };

  // 영화관 굿즈 배부 시간(현장 매표/매점 운영): 08:00~24:00 로 가정. 이 시간 밖에서는 재고가 줄지 않는다고 본다.
  const OPEN_H = 8, CLOSE_H = 24;
  function dayOpen(t) { const d = new Date(t); d.setHours(OPEN_H, 0, 0, 0); return d.getTime(); }
  function dayClose(t) { const d = new Date(t); d.setHours(0, 0, 0, 0); return d.getTime() + CLOSE_H * H; }
  // t0~t1 사이의 영업 시간(ms)
  function openMs(t0, t1) {
    if (t1 <= t0) return 0;
    let sum = 0; let cur = t0;
    for (let i = 0; i < 400 && cur < t1; i++) {
      const o = dayOpen(cur), c = dayClose(cur);
      const a = Math.max(cur, o), b = Math.min(t1, c);
      if (b > a) sum += b - a;
      const d = new Date(cur); d.setHours(0, 0, 0, 0); d.setDate(d.getDate() + 1); cur = d.getTime();
    }
    return sum;
  }
  // t 에서 영업시간 ms 만큼 지난 시각
  function addOpen(t, ms) {
    let cur = t;
    for (let i = 0; i < 400; i++) {
      const o = dayOpen(cur), c = dayClose(cur);
      if (cur < o) cur = o;
      if (cur < c) { if (cur + ms <= c) return cur + ms; ms -= c - cur; }
      const d = new Date(cur); d.setHours(0, 0, 0, 0); d.setDate(d.getDate() + 1); cur = d.getTime();
    }
    return cur;
  }
  GC.openMs = openMs; GC.addOpen = addOpen;
  const clampP = (p) => Math.min(0.97, Math.max(0.02, p));

  function median(arr) {
    if (!arr || !arr.length) return null;
    const a = [...arr].sort((x, y) => x - y);
    const m = a.length >> 1;
    return a.length % 2 ? a[m] : (a[m - 1] + a[m]) / 2;
  }

  GC.histKey = (evId, goodsId, theater) => `${evId}|${goodsId}|${theater}`;
  const LV = ['out', 'few', 'some', 'plenty'];

  // 오늘 영업 종료 시각(다음날 0시 기준; 심야 회차는 무시)
  function endOfToday(now) {
    const d = new Date(now); d.setHours(24, 0, 0, 0); return d.getTime();
  }
  function endOfDate(ymd) {
    if (!ymd) return Infinity;
    const [y, m, d] = ymd.split('-').map(Number);
    return new Date(y, m - 1, d, 24, 0, 0, 0).getTime();
  }

  // 수량 이력 → 시간당 감소 속도(최근 가중). 증가(재입고)는 구간 무시.
  function countRate(points, now) {
    const p = points.filter((x) => x[2] != null && now - x[0] < 36 * H);
    if (p.length < 2) return null;
    let used = 0, wsum = 0, span = 0;
    for (let i = 1; i < p.length; i++) {
      const dt = openMs(p[i - 1][0], p[i][0]) / H;
      const dc = p[i - 1][2] - p[i][2];
      if (dt <= 0 || dc < 0) continue;
      const w = Math.exp(-(now - p[i][0]) / (6 * H)); // 6시간 반감 가중
      used += w * dc; wsum += w * dt; span += dt;
    }
    // 마지막 관측 이후 지금까지 변화 없음도 반영(속도 둔화)
    const last = p[p.length - 1];
    const idle = openMs(last[0], now) / H;
    if (idle > 0) { const w = 1; wsum += w * Math.min(idle, 6); span += Math.min(idle, 6); }
    if (wsum <= 0) return null;
    return { rate: used / wsum, span, n: p.length };
  }

  // 단계 이력 → 현재 단계 진입 시각
  function levelSince(points, level) {
    let since = null;
    for (let i = points.length - 1; i >= 0; i--) {
      if (points[i][1] === level) since = points[i][0]; else break;
    }
    return since;
  }

  function logistic(x) { return 1 / (1 + Math.exp(-x)); }

  /**
   * @returns {perGoods: {goodsId: {theaters:[{theater, level, count, eta, prob, basis}], todayOut, total, outNow, prob}}, summary}
   */
  GC.predictEvent = function (ev, history, learn, now) {
    now = now || Date.now();
    const result = { perGoods: {}, best: null };
    if (!ev.stock || !ev.stock.length) return result;
    const today = GC.todayStr(new Date(now));
    if (ev.start && ev.start > today) { result.notStarted = true; return result; }
    const cutoff = Math.min(endOfToday(now), endOfDate(ev.end));
    const chain = ev.chain;
    const L = (learn && learn[chain]) || {};

    const byGoods = {};
    for (const s of ev.stock) (byGoods[s.goodsId] || (byGoods[s.goodsId] = [])).push(s);

    for (const gid of Object.keys(byGoods)) {
      const rows = byGoods[gid];
      const total = rows.filter((r) => r.level !== 'ready' && r.level !== 'unknown').length;
      const outNow = rows.filter((r) => r.level === 'out').length;
      const outShare = total ? outNow / total : 0;
      // 교차 지점 평균 속도(롯데)
      const rates = [];
      for (const r of rows) {
        const h = history[GC.histKey(ev.id, gid, r.theater)] || [];
        const cr = countRate(h, now);
        if (cr && cr.rate > 0) rates.push(cr.rate);
      }
      const crossRate = median(rates);
      const theaters = [];
      for (const r of rows) {
        const h = history[GC.histKey(ev.id, gid, r.theater)] || [];
        const t = { theater: r.theater, level: r.level, count: r.count, eta: null, prob: null, basis: '' };
        if (r.level === 'out') { t.prob = 1; t.basis = '이미 소진'; theaters.push(t); continue; }
        if (r.level === 'ready' || r.level === 'unknown') { t.basis = r.level === 'ready' ? '배부 준비중' : '정보 없음'; theaters.push(t); continue; }
        let eta = null, sigma = null;
        if (ev.stockKind === 'count' && r.count != null) {
          const cr = countRate(h, now);
          let rate = null;
          if (cr && cr.rate > 0 && cr.span >= 0.5) { rate = cr.rate; t.basis = `이 지점 최근 속도 ${rate.toFixed(1)}개/시간`; sigma = Math.max(0.75, 3 / Math.sqrt(cr.n)) * H; }
          else if (crossRate) { rate = crossRate; t.basis = `같은 굿즈 타 지점 평균 ${rate.toFixed(1)}개/시간`; sigma = 3 * H; }
          else if (L.countRate) { rate = L.countRate; t.basis = `롯데 과거 굿즈 평균 ${rate.toFixed(1)}개/시간`; sigma = 5 * H; }
          if (rate) eta = addOpen(now, (r.count / rate) * H);
          else { t.basis = '감소 관측 전(데이터 수집 중)'; }
        } else {
          const lvMed = (L.levelToOut && median(L.levelToOut[r.level])) || (DEFAULT_LEVEL_TO_OUT[chain] || DEFAULT_LEVEL_TO_OUT.CGV)[r.level];
          const nLearn = (L.levelToOut && L.levelToOut[r.level] && L.levelToOut[r.level].length) || 0;
          const since = levelSince(h, r.level) || (h.length ? h[0][0] : now);
          const elapsed = openMs(since, now);
          let remain = lvMed * H - elapsed;
          // 수요 신호: 서울 지점 소진 비율이 높으면 남은 시간 단축
          const factor = 1 - 0.6 * outShare;
          remain = Math.max(remain * factor, 0.25 * H);
          eta = addOpen(now, remain);
          sigma = Math.max(1, (nLearn >= 10 ? 0.45 : 0.7) * lvMed * factor) * H;
          t.basis = `'${GC.levelLabel[r.level]}' 단계 진입 후 영업시간 ${(elapsed / H).toFixed(1)}h · 단계→소진 중앙값 ${lvMed.toFixed(1)}h${nLearn ? ` (학습 ${nLearn}건)` : ' (기본값)'}${outNow ? ` · 서울 ${outNow}/${total}곳 소진` : ''}`;
        }
        if (eta) {
          t.eta = eta;
          // 시간차를 영업시간 기준으로 환산(밤 시간은 불확실성에 넣지 않음)
          const gap = eta <= cutoff ? openMs(eta, cutoff) : -openMs(cutoff, eta);
          t.prob = clampP(logistic(gap / (sigma || 3 * H) * 1.7));
        }
        theaters.push(t);
      }
      const live = theaters.filter((t) => t.prob != null && t.level !== 'out');
      const todayOut = live.filter((t) => t.prob >= 0.6).length;
      // 서울 "전 지점" 오늘 소진 확률 ≈ 남은 지점 확률의 곱(독립 가정)
      const allProb = live.length ? live.reduce((a, t) => a * t.prob, 1) : (outNow === total && total ? 1 : null);
      const maxProb = live.length ? Math.max(...live.map((t) => t.prob)) : null;
      result.perGoods[gid] = { theaters, total, outNow, todayOut, allProb, maxProb, live: live.length };
    }
    // 이벤트 대표값: 가장 위험한 굿즈 기준
    let best = null;
    for (const [gid, g] of Object.entries(result.perGoods)) {
      if (g.maxProb == null) continue;
      if (!best || g.maxProb > best.maxProb) best = Object.assign({ goodsId: gid }, g);
    }
    result.best = best;
    return result;
  };

  GC.predictLabel = function (p) {
    if (p == null) return null;
    if (p >= 0.75) return { cls: 'hot', text: '오늘 소진 예상' };
    if (p >= 0.45) return { cls: 'warm', text: '오늘 소진 가능' };
    return { cls: 'cool', text: '오늘은 여유' };
  };

  // 이력에서 학습: 단계 진입 → 소진까지 걸린 시간, 롯데 평균 감소 속도
  GC.learnFromHistory = function (history, eventsById, prevLearn) {
    const learn = prevLearn ? JSON.parse(JSON.stringify(prevLearn)) : {};
    const seenKeys = new Set((learn._done || []));
    for (const [key, pts] of Object.entries(history)) {
      if (seenKeys.has(key) || pts.length < 2) continue;
      const evId = key.split('|')[0];
      const chain = evId.split(':')[0];
      const last = pts[pts.length - 1];
      if (last[1] !== 'out') continue;
      const L = learn[chain] || (learn[chain] = { levelToOut: {}, countRates: [] });
      L.levelToOut = L.levelToOut || {};
      const outAt = last[0];
      // 각 단계에 처음 들어간 시각 → 소진 시각
      const firstAt = {};
      for (const p of pts) if (p[1] !== 'out' && firstAt[p[1]] == null) firstAt[p[1]] = p[0];
      for (const [lv, t] of Object.entries(firstAt)) {
        // 첫 관측이 그 단계의 "시작"이 아닐 수 있음(확장 설치 전부터 그 단계) → 첫 포인트가 그 단계면 하한값이라 제외
        if (pts[0][1] === lv && pts[0][0] === t && lv !== 'plenty') continue;
        const hrs = openMs(t, outAt) / H;
        if (hrs > 0 && hrs < 16 * 14) (L.levelToOut[lv] || (L.levelToOut[lv] = [])).push(+hrs.toFixed(2));
      }
      if (pts[0][2] != null) {
        const first = pts.find((p) => p[2] > 0);
        if (first) {
          const hrs = openMs(first[0], outAt) / H;
          if (hrs > 0.2) { L.countRates = L.countRates || []; L.countRates.push(+(first[2] / hrs).toFixed(2)); }
        }
      }
      seenKeys.add(key);
    }
    for (const c of Object.keys(learn)) {
      if (c === '_done') continue;
      const L = learn[c];
      for (const lv of Object.keys(L.levelToOut || {})) L.levelToOut[lv] = L.levelToOut[lv].slice(-400);
      if (L.countRates) { L.countRates = L.countRates.slice(-400); L.countRate = median(L.countRates); }
    }
    learn._done = [...seenKeys].slice(-5000);
    return learn;
  };
})(typeof self !== 'undefined' ? self : globalThis);

