/* 영화굿즈 캘린더 — 영화관별 데이터 수집기
 * 서비스워커(importScripts)와 페이지(테스트) 양쪽에서 동작하도록 DOM 없이 작성.
 * ctx = { get(url), postJSON(url,obj), postForm(url,fields), sleep(ms), cache:{}, log(msg) }
 */
(function (G) {
  const GC = G.GC || (G.GC = {});

  // ───────── 공통 유틸 ─────────
  const GOODS_RE = /증정|굿즈|현장\s?이벤트|패키지|포스터|엽서|키링|아트\s?카드|art\s?card|TTT|필름마크|북마크|스티커|배지|뱃지|씰|코스터|렌티큘러|풀백카|오리지널\s?티켓|브로마이드|부클릿|booklet|핀버튼|핀뱃지|퍼즐|틴케이스|포토카드|xtracollection/i;
  const EXCLUDE_RE = /빵원|0원딜|무비0원|할인|결제|청년문화|군인|경찰|멤버십|포인트|통신사|당첨자|특가|티빙|구독|N차 관람|생일기념|오픈 기념 콤보|팝콘|콤보|음료/;
  const SALE_RE = /출시|런칭|예약판매|판매|굿즈샵|스토어/;
  const PACKAGE_RE = /굿즈\s?패키지|패키지\s?상영|굿즈\s?상영회|굿즈상영|패키지 티켓|굿즈패키지/;
  const TICKET_RE = /아트\s?카드|art\s?card|TTT|필름마크|오리지널\s?티켓|signature|xtracollection|스페셜\s?티켓|special ticket/i;
  const SCREENING_RE = /상영회|토크|GV|프리미어|씨네토크|메가토크|라이브뷰잉/i;

  GC.classify = function (title, goodsNames) {
    const t = title + ' ' + (goodsNames || []).join(' ');
    if (PACKAGE_RE.test(t)) return '굿즈패키지';
    if (SALE_RE.test(title) && !/증정/.test(title)) return '굿즈 판매';
    if (TICKET_RE.test(t)) return '스페셜 티켓·카드';
    if (SCREENING_RE.test(title)) return '상영회 증정';
    return '현장 증정';
  };

  GC.isGoodsEvent = function (title, hasStock) {
    if (EXCLUDE_RE.test(title) && !/증정|굿즈/.test(title)) return false;
    return hasStock || GOODS_RE.test(title);
  };

  GC.decode = function (s) {
    if (s == null) return '';
    let out = String(s);
    for (let i = 0; i < 5; i++) {
      const prev = out;
      out = out
        .replace(/&#x([0-9a-f]+);/gi, (_, h) => String.fromCodePoint(parseInt(h, 16)))
        .replace(/&#(\d+);/g, (_, d) => String.fromCodePoint(parseInt(d, 10)))
        .replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/&quot;/g, '"')
        .replace(/&#39;|&apos;/g, "'").replace(/&nbsp;/g, ' ').replace(/&middot;/g, '·')
        .replace(/&amp;/g, '&');
      if (out === prev) break;
    }
    return out;
  };

  GC.stripTags = function (html) {
    return GC.decode(String(html || '')
      .replace(/<br\s*\/?>/gi, '\n').replace(/<\/p>/gi, '\n')
      .replace(/<script[\s\S]*?<\/script>/gi, '').replace(/<style[\s\S]*?<\/style>/gi, '')
      .replace(/<[^>]+>/g, ' ')).replace(/[ \t ]+/g, ' ').replace(/\s*\n\s*/g, '\n').trim();
  };

  const pad = (n) => String(n).padStart(2, '0');
  // '2026.10.28' '26.10.28' '20261028' '2026-10-28' '26.11.4' '2026.11.04(수)'
  GC.parseDate = function (s, refYear) {
    if (!s) return null;
    s = String(s).trim();
    let m = s.match(/^(\d{4})(\d{2})(\d{2})/);
    if (m) return `${m[1]}-${m[2]}-${m[3]}`;
    m = s.match(/(\d{2,4})[.\-/](\d{1,2})[.\-/](\d{1,2})/);
    if (m) {
      let y = +m[1]; if (y < 100) y += 2000;
      return `${y}-${pad(m[2])}-${pad(m[3])}`;
    }
    m = s.match(/(\d{1,2})\s*[.\/월]\s*(\d{1,2})/);
    if (m && refYear) return `${refYear}-${pad(m[1])}-${pad(m[2])}`;
    return null;
  };

  GC.todayStr = function (d) {
    d = d || new Date();
    return `${d.getFullYear()}-${pad(d.getMonth() + 1)}-${pad(d.getDate())}`;
  };

  // 제목에서 영화명 추출: <...>(중첩 허용) 우선, 그다음 머리 [..]
  const TAG_WORDS = /^(라이브뷰잉|굿즈패키지|굿즈 패키지|NT Live|\d{4}.*|메트오페라|RE:Masterpiece|씨집에 가면|특가|단독|이벤트|공지|현장이벤트|ICECON|아트하우스|CGV|SPECIAL|스페셜)$/i;
  GC.extractMovie = function (title) {
    if (!title) return null;
    title = GC.decode(title);
    const a = title.indexOf('<');
    if (a >= 0) {
      let depth = 0;
      for (let i = a; i < title.length; i++) {
        if (title[i] === '<') depth++;
        else if (title[i] === '>') { depth--; if (depth === 0) return cleanMovie(title.slice(a + 1, i)); }
      }
    }
    const br = [...title.matchAll(/\[([^\]]+)\]/g)].map((m) => m[1].trim());
    for (const b of br) if (!TAG_WORDS.test(b)) return cleanMovie(b);
    const cr = title.match(/[『「]([^』」]+)[』」]/);
    if (cr) return cleanMovie(cr[1]);
    return null;
  };
  function cleanMovie(s) {
    return s.replace(/\s+/g, ' ').replace(/^(극장판)\s*/, '극장판 ').trim();
  }
  // 체인마다 표기가 달라도 묶이도록 정규화 키
  GC.movieKey = function (name) {
    if (!name) return '__etc';
    return name.toLowerCase().replace(/[^0-9a-z가-힣]/g, '');
  };

  // 굿즈 구성이 이미지로만 공지된 이벤트: 제목에서 굿즈명 부분만 추출 (예: "<하트 오브 비스트> 1주차 오딘 키링 선착순 증정 이벤트" → "오딘 키링")
  GC.goodsFromTitle = function (title) {
    if (!title) return null;
    let t = GC.decode(title);
    const mv = GC.extractMovie(t);
    if (mv) t = t.replace('<' + mv + '>', ' ').replace('[' + mv + ']', ' ');
    t = t.replace(/\[[^\]]*\]|<[^>]*>/g, ' ')
      .replace(/(재+)?개봉\s*(\d+주차)?\s*(기념)?/g, ' ').replace(/\d+\s*주차/g, ' ')
      .replace(/주말|주중|평일|선착순|현장|증정|이벤트|상영회|기념|관람객\s*대상|오픈|_[^\s]+관$/g, ' ')
      .replace(/[_·\-]+/g, ' ').replace(/\s+/g, ' ').trim();
    if (t.length < 2 || !GOODS_RE.test(t + ' 증정') || /^(이벤트|현장 이벤트)$/.test(t)) return null;
    return GOODS_RE.test(t) ? t : null;
  };

  // 수량/상태 → 공통 레벨: plenty | some | few | out | ready | unknown
  GC.levelLabel = {
    plenty: '여유', some: '소진 중', few: '소진 임박', out: '소진', ready: '준비중', unknown: '정보 없음'
  };

  function mkId(chain, id) { return chain + ':' + id; }

  // ───────── CGV ─────────
  // 경품현황 API (cgv.co.kr/evt/giveawayState 화면이 쓰는 것과 동일)
  const CGV = 'https://cgv.co.kr/api/v1/content/event';
  const CGV_LEVEL = { green: 'plenty', yellow: 'some', red: 'few', gray: 'out' };

  GC.fetchCGV = async function (ctx, opts) {
    opts = opts || {};
    const delay = opts.delay ?? 1500;
    const errors = [];
    const events = [];
    const listTxt = await ctx.get(`${CGV}/saprm/saprm/searchSaprmEvtListForPage?coCd=A420&startRow=0&listCount=200`);
    const list = JSON.parse(listTxt).data.list || [];
    const prodCache = ctx.cache.cgvProd || (ctx.cache.cgvProd = {});
    for (const e of list) {
      const title = GC.decode(e.evntOnlnExpoNm || e.saprmEvntNm);
      const ev = {
        id: mkId('CGV', e.saprmEvntNo), chain: 'CGV', source: 'CGV', title,
        movie: GC.extractMovie(title),
        start: GC.parseDate(e.evntStartYmd), end: GC.parseDate(e.evntEndYmd),
        url: `https://cgv.co.kr/evt/giveawayStateDetail?saprmEvntNo=${e.saprmEvntNo}`,
        image: e.saprmEvntImageUrl || null,
        allOut: e.exhsYn === 'Y',
        goods: [], stock: [], stockKind: 'level', stockOk: false
      };
      try {
        let prods = prodCache[e.saprmEvntNo];
        if (!prods) {
          await ctx.sleep(delay);
          prods = JSON.parse(await ctx.get(`${CGV}/saprm/saprm/searchSaprmEvtProdList?coCd=A420&saprmEvntNo=${e.saprmEvntNo}`)).data || [];
          prodCache[e.saprmEvntNo] = prods;
        }
        for (const p of prods) {
          const g = {
            id: p.spmtlNo, name: GC.decode(p.onlnExpoNm || p.spmtlProdNm),
            desc: GC.decode(p.spmtlDsc || '').replace(/^.*?\n/, '').trim()
          };
          ev.goods.push(g);
          if (ev.allOut || opts.skipStock) continue;
          await ctx.sleep(delay);
          const sites = JSON.parse(await ctx.get(`${CGV}/saprm/saprm/searchSaprmEvtTgtsiteList?coCd=A420&saprmEvntNo=${e.saprmEvntNo}&spmtlNo=${p.spmtlNo}`)).data || [];
          for (const s of sites) {
            if (s.regnGrpCd !== '01') continue; // 서울만
            ev.stock.push({
              goodsId: g.id, theater: 'CGV ' + (s.expoSiteNm || s.siteNm.replace(/^CGV\s*/, '')),
              theaterId: s.siteNo, level: CGV_LEVEL[s.inventStatus] || 'unknown', raw: s.inventStatus,
              onlineApply: s.fcfsPayYn === 'Y'
            });
          }
          ev.stockOk = true;
        }
        if (ev.allOut) { ev.stockOk = true; ev.allOutNote = 'CGV 전 지점 소진(이벤트 종료)'; }
      } catch (err) {
        if (err && err.rateLimited) throw err; // 상위에서 백오프
        errors.push(`${title}: ${err.message || err}`);
      }
      ev.type = GC.classify(title, ev.goods.map((g) => g.name));
      events.push(ev);
    }
    return { events, errors };
  };

  // ───────── 메가박스 ─────────
  const MB = 'https://www.megabox.co.kr';
  const MB_LEVEL = { '보유': 'plenty', '소량보유': 'few', '소진': 'out', '준비중': 'ready' };

  GC.parseMegaboxList = function (html) {
    const out = [];
    const re = /<a[^>]*data-no="(\d+)"[^>]*>([\s\S]*?)<\/a>/g;
    let m;
    while ((m = re.exec(html))) {
      const inner = m[2].replace(/<!--[\s\S]*?-->/g, '');
      const tit = (inner.match(/<p class="tit">([\s\S]*?)<\/p>/) || [])[1];
      const date = (inner.match(/<p class="date">([\s\S]*?)<\/p>/) || [])[1] || '';
      const img = (inner.match(/<img[^>]*src="([^"]+)"/) || [])[1];
      const ds = date.match(/(\d{4}\.\d{2}\.\d{2})\s*~\s*(\d{4}\.\d{2}\.\d{2})/);
      out.push({
        no: m[1], title: GC.stripTags(tit || ''),
        start: ds ? GC.parseDate(ds[1]) : null, end: ds ? GC.parseDate(ds[2]) : null,
        image: img && !/noImg|@img/.test(img) ? img : null
      });
    }
    return out;
  };

  GC.parseMegaboxGoodsButtons = function (html) {
    const out = [];
    const re = /<button[^>]*data-pn="([^"]+)"[^>]*>/g;
    let m;
    while ((m = re.exec(html))) {
      const nm = (m[0].match(/data-nm="([^"]*)"/) || [])[1] || '';
      if (!out.find((x) => x.id === m[1])) out.push({ id: m[1], name: GC.decode(nm).replace(/\s+/g, ' ').trim() });
    }
    return out;
  };

  GC.parseMegaboxStock = function (html) {
    // area-cont 블록별(id=지역코드) 지점 상태 — 서울은 id="10"
    const res = [];
    const blocks = html.split(/<li class="area-cont[^"]*"/).slice(1);
    for (const b of blocks) {
      const area = (b.match(/^\s*id="(\d+)"/) || [])[1];
      const areaName = ((b.match(/<button[^>]*>([^<(]+)/) || [])[1] || '').trim();
      const re = /<li([^>]*)class="brch"([^>]*)>\s*<a>([\s\S]*?)<\/a>\s*<span[^>]*>([\s\S]*?)<\/span>/g;
      let m;
      while ((m = re.exec(b))) {
        const attrs = m[1] + m[2];
        const id = (attrs.match(/brchCd="(\d+)"/i) || attrs.match(/id="(\d+)"/) || [])[1] || null;
        res.push({ area, areaName, brchNo: id, theater: GC.stripTags(m[3]), status: GC.stripTags(m[4]) });
      }
    }
    return res;
  };

  GC.fetchMegabox = async function (ctx, opts) {
    opts = opts || {};
    const delay = opts.delay ?? 350;
    const errors = [];
    const events = [];
    const seen = new Set();
    let items = [];
    for (const div of ['CED01', 'CED02']) {
      const html = await ctx.postJSON(`${MB}/on/oh/ohe/Event/eventMngDiv.do`, {
        currentPage: '1', recordCountPerPage: '1000', eventStatCd: 'ONG', eventTitle: '',
        eventDivCd: div, eventTyCd: '', orderReqCd: 'ONGlist'
      });
      for (const it of GC.parseMegaboxList(html)) if (!seen.has(it.no)) { seen.add(it.no); items.push(it); }
    }
    const btnCache = ctx.cache.mbBtn || (ctx.cache.mbBtn = {});
    for (const it of items) {
      // 극장(CED02) 이벤트는 굿즈 키워드 있는 것만 상세 조회(속도)
      const maybe = GC.isGoodsEvent(it.title, false) || SCREENING_RE.test(it.title);
      if (!maybe) continue;
      const ev = {
        id: mkId('MEGABOX', it.no), chain: 'MEGABOX', source: '메가박스', title: it.title,
        movie: GC.extractMovie(it.title), start: it.start, end: it.end,
        url: `${MB}/event/detail?eventNo=${it.no}`, image: it.image,
        goods: [], stock: [], stockKind: 'level', stockOk: false
      };
      try {
        let btns = btnCache[it.no];
        if (!btns) {
          await ctx.sleep(delay);
          btns = GC.parseMegaboxGoodsButtons(await ctx.get(`${MB}/event/detail?eventNo=${it.no}`));
          btnCache[it.no] = btns;
        }
        for (const b of btns) {
          const g = { id: b.id, name: b.name.replace(/^\[굿즈패키지\]\s*/, ''), isPackage: /^\[굿즈패키지\]/.test(b.name) };
          ev.goods.push(g);
          if (opts.skipStock) continue;
          await ctx.sleep(delay);
          const st = GC.parseMegaboxStock(await ctx.postJSON(`${MB}/on/oh/ohe/Event/selectGoodsStockPrco.do`, { eventNo: it.no, goodsNo: b.id }));
          for (const s of st) {
            if (s.area !== '10') continue;
            ev.stock.push({ goodsId: g.id, theater: '메가박스 ' + s.theater, theaterId: s.brchNo, level: MB_LEVEL[s.status.replace(/\s/g, '')] || 'unknown', raw: s.status });
          }
          ev.stockOk = true;
        }
      } catch (err) {
        if (err && err.rateLimited) throw err;
        errors.push(`${it.title}: ${err.message || err}`);
      }
      if (!GC.isGoodsEvent(it.title, ev.goods.length > 0)) continue;
      // 서울 지점이 하나도 없는 이벤트(지방 극장 이벤트)는 제외
      if (ev.stockOk && ev.goods.length && ev.stock.length === 0) continue;
      ev.type = GC.classify(it.title, ev.goods.map((g) => (g.isPackage ? '굿즈패키지 ' : '') + g.name));
      events.push(ev);
    }
    return { events, errors };
  };

  // ───────── 롯데시네마 ─────────
  const LC = 'https://www.lottecinema.co.kr';
  async function lcCall(ctx, params) {
    const p = Object.assign({ channelType: 'HO', osType: 'W', osVersion: 'Chrome' }, params);
    const txt = await ctx.postForm(`${LC}/LCWS/Event/EventData.aspx`, { paramList: JSON.stringify(p) });
    const j = JSON.parse(txt);
    if (String(j.IsOK) !== 'true') throw new Error('롯데 API 응답 오류: ' + (j.ResultMessage || ''));
    return j;
  }
  GC.lcLevel = function (cnt) {
    if (cnt == null || isNaN(cnt)) return 'unknown';
    if (cnt <= 0) return 'out';
    if (cnt <= 30) return 'few';
    if (cnt <= 100) return 'some';
    return 'plenty';
  };

  GC.fetchLotte = async function (ctx, opts) {
    opts = opts || {};
    const delay = opts.delay ?? 250;
    const errors = [];
    const events = [];
    const seen = new Set();
    const all = [];
    // 10: 영화, 20: 굿즈, 40: 시사회/무대인사(굿즈 상영회 포함)
    for (const code of ['20', '10', '40']) {
      const j = await lcCall(ctx, { MethodName: 'GetEventLists', EventClassificationCode: code, SearchText: '', CinemaID: '', PageNo: 1, PageSize: 300, MemberNo: '0' });
      for (const it of j.Items || []) if (!seen.has(it.EventID)) { seen.add(it.EventID); it._code = code; all.push(it); }
    }
    const giftCache = ctx.cache.lcGift || (ctx.cache.lcGift = {});
    for (const it of all) {
      const title = GC.decode(it.EventName).trim();
      // 20(굿즈) 분류는 전부, 나머지 분류는 굿즈 키워드가 있는 것만
      if (it._code !== '20' && !GC.isGoodsEvent(title, false)) continue;
      if (it._code === '20' && EXCLUDE_RE.test(title) && !/증정|굿즈/.test(title)) continue;
      // 지점 한정 이벤트(서울 외 지점)는 제외
      if (it.CinemaAreaName && !/서울/.test(it.CinemaAreaName)) continue;
      const ev = {
        id: mkId('LOTTE', it.EventID), chain: 'LOTTE', source: '롯데시네마', title,
        movie: GC.extractMovie(title),
        start: GC.parseDate(it.ProgressStartDate), end: GC.parseDate(it.ProgressEndDate),
        url: `${LC}/NLCHS/Event/EventTemplateInfo?eventId=${it.EventID}`,
        image: (it.ImageUrl || '').replace(/^http:/, 'https:') || null,
        branchOnly: it.CinemaName ? '롯데시네마 ' + it.CinemaName : null,
        goods: [], stock: [], stockKind: 'count', stockOk: false
      };
      const note = GC.stripTags(it.EventNtc || '');
      if (note && note.length < 600) ev.note = note;
      try {
        let gifts = giftCache[it.EventID];
        if (!gifts) {
          await ctx.sleep(delay);
          const d = await lcCall(ctx, { MethodName: 'GetInfomationDeliveryEventDetail', EventID: it.EventID });
          const x = (d.InfomationDeliveryEventDetail || [])[0] || {};
          gifts = (x.GoodsGiftItems || []).map((g) => ({ id: String(g.FrGiftID), name: GC.decode(g.FrGiftNm) }));
          // 증정품 목록이 아직 비어있으면(오픈 전) 캐시하지 않음 → 다음 갱신 때 재확인
          if (gifts.length) giftCache[it.EventID] = gifts;
        }
        for (const g of gifts) {
          ev.goods.push(g);
          if (opts.skipStock) continue;
          await ctx.sleep(delay);
          const s = await lcCall(ctx, { MethodName: 'GetCinemaGoods', EventID: it.EventID, GiftID: g.id });
          for (const c of s.CinemaDivisionGoods || []) {
            if (String(c.DetailDivisionCode) !== '0001') continue; // 서울
            const cnt = Number(c.Cnt);
            ev.stock.push({ goodsId: g.id, theater: '롯데시네마 ' + c.CinemaNameKR, theaterId: String(c.CinemaID), count: cnt, level: GC.lcLevel(cnt) });
          }
          ev.stockOk = true;
        }
      } catch (err) {
        if (err && err.rateLimited) throw err;
        errors.push(`${title}: ${err.message || err}`);
      }
      // 증정품 재고가 있는데 서울 지점이 하나도 없으면(지방 지점 한정) 제외
      if (ev.stockOk && ev.goods.length && ev.stock.length === 0) continue;
      // 제목에 서울 외 지점명이 명시된 경우 제외 (예: _경기인디시네마관)
      if (/_(경기|인천|부산|대구|광주|대전|울산|수원|부천|김해|창원|전주|청주|천안)/.test(title)) continue;
      ev.type = GC.classify(title, ev.goods.map((g) => g.name));
      events.push(ev);
    }
    return { events, errors };
  };

  // ───────── 씨네Q (서울: 신도림) ─────────
  GC.fetchCineQ = async function (ctx) {
    const events = []; const errors = [];
    let lastId = 0;
    for (let page = 0; page < 6; page++) {
      const txt = await ctx.postFormUrl('https://www.cineq.co.kr/Event/MoreList', { eventId: String(lastId), eventSort: '-1' });
      const arr = JSON.parse(txt);
      if (!arr.length) break;
      let anyActive = false;
      for (const e of arr) {
        lastId = e.EventId;
        if (String(e.Status) !== '1') continue;
        anyActive = true;
        const title = GC.decode(e.Title).trim();
        if (!GC.isGoodsEvent(title, false)) continue;
        const ds = String(e.Duration || '').split('~');
        events.push({
          id: mkId('CINEQ', e.EventId), chain: 'CINEQ', source: '씨네Q', title, movie: GC.extractMovie(title),
          start: GC.parseDate(ds[0]), end: GC.parseDate(ds[1] || ds[0]),
          url: `https://www.cineq.co.kr/Event/Info?eventId=${e.EventId}&eventSort=-1`,
          image: e.Thumb || null, branchOnly: '씨네Q 신도림 (전 지점 공통 이벤트)',
          goods: [], stock: [], stockKind: 'none', stockOk: false,
          type: GC.classify(title, [])
        });
      }
      if (!anyActive) break;
      await ctx.sleep(300);
    }
    return { events, errors };
  };

  // ───────── 씨네큐브 광화문 ─────────
  GC.parseCinecube = function (html) {
    const out = [];
    const re = /<a href="\/event\/view\/(\d+)"[^>]*>([\s\S]*?)<\/a>/g;
    let m;
    const seen = new Set();
    while ((m = re.exec(html))) {
      if (seen.has(m[1])) continue;
      const inner = m[2];
      const alt = (inner.match(/alt="([^"]*)"/) || [])[1];
      const img = (inner.match(/<img[^>]*src="([^"]+)"/) || [])[1];
      const text = GC.stripTags(inner);
      const ds = text.match(/(\d{2,4}\.\d{1,2}\.\d{1,2})\s*~\s*(\d{2,4}\.\d{1,2}\.\d{1,2})/);
      if (!ds) continue;
      seen.add(m[1]);
      out.push({ id: m[1], title: GC.decode(alt || text.replace(/기간.*?\d{2}\s/, '')).trim(), start: GC.parseDate(ds[1]), end: GC.parseDate(ds[2]), image: img ? 'https://www.cinecube.co.kr' + img : null, closed: /마감|소진|조기\s?종료/.test(text) });
    }
    return out;
  };
  GC.fetchCinecube = async function (ctx) {
    const events = []; const errors = [];
    for (const grp of ['EG001', 'EG002', 'EG004,EG005,EG006']) {
      try {
        const html = await ctx.get('https://www.cinecube.co.kr/event/' + grp);
        for (const e of GC.parseCinecube(html)) {
          if (!GC.isGoodsEvent(e.title, false)) continue;
          if (events.find((x) => x.id === mkId('CINECUBE', e.id))) continue;
          events.push({
            id: mkId('CINECUBE', e.id), chain: 'CINECUBE', source: '씨네큐브', title: e.title, movie: GC.extractMovie(e.title),
            start: e.start, end: e.end, url: 'https://www.cinecube.co.kr/event/view/' + e.id, image: e.image,
            branchOnly: '씨네큐브 광화문', goods: [], stock: [], stockKind: 'none', stockOk: false,
            allOut: e.closed, allOutNote: e.closed ? '씨네큐브 게시판에 마감 표시' : null,
            type: GC.classify(e.title, [])
          });
        }
      } catch (err) { errors.push(grp + ': ' + (err.message || err)); }
      await ctx.sleep(300);
    }
    return { events, errors };
  };

  // ───────── 독립영화관 (imweb 게시판형: 라이카시네마 등) ─────────
  GC.parseImwebBoard = function (html, base) {
    const out = [];
    const cards = html.replace(/<!--[\s\S]*?-->/g, '').split(/class=['"]list-style-card/).slice(1);
    for (const c of cards) {
      const idx = (c.match(/idx=(\d+)/) || [])[1];
      const tb = c.match(/class="title title-block"[^>]*>([\s\S]*?)<\/div>/);
      if (!idx || !tb) continue;
      let text = GC.stripTags(tb[1]).replace(/-->/g, ' ').replace(/\s+/g, ' ').trim();
      text = text.replace(/^공지\s*/, '');
      let status = null;
      const sm = text.match(/^(진행\s?예정|진행\s?중|종료|마감)\s*/);
      if (sm) { status = sm[1].replace(/\s/g, ''); text = text.slice(sm[0].length); }
      text = text.replace(/\s+N$/, '').trim();
      const posted = (c.match(/class="date"[^>]*title="(\d{4}-\d{2}-\d{2})/) || [])[1] || null;
      const img = (c.match(/data-original="([^"]+)"/) || [])[1] || null;
      out.push({ idx, title: text, status, posted, image: img, url: `${base}/?bmode=view&idx=${idx}&t=board` });
    }
    return out;
  };

  // 본문에서 기간 추정: "2026.10.29 ~ 11.4", "10월 29일(수) ~ 11월 4일", "10/29~11/4", "시작일: 10/28(수)"
  GC.guessPeriod = function (text, refYear) {
    const t = text.replace(/\s+/g, ' ');
    const D = '(?:(\\d{4})\\s*[.\\-/년]\\s*)?(\\d{1,2})\\s*[.\\-/월]\\s*(\\d{1,2})\\s*일?(?:\\s*\\([^)]{1,4}\\))?';
    const re = new RegExp(D + '\\s*[~\\-–]\\s*' + D);
    const m = t.match(re);
    const ok = (mo, d) => +mo >= 1 && +mo <= 12 && +d >= 1 && +d <= 31;
    if (m && ok(m[2], m[3]) && ok(m[5], m[6])) {
      const y1 = +(m[1] || refYear), y2 = +(m[4] || y1);
      const s = `${y1}-${pad(m[2])}-${pad(m[3])}`;
      let e = `${y2}-${pad(m[5])}-${pad(m[6])}`;
      if (e < s && !m[4]) e = `${y1 + 1}-${pad(m[5])}-${pad(m[6])}`;
      return { start: s, end: e };
    }
    const one = t.match(new RegExp('(시작일|기간|일시|일자|날짜|증정일)\\s*[:：]?\\s*' + D));
    if (one && ok(one[3], one[4])) {
      const y = +(one[2] || refYear); const d = `${y}-${pad(one[3])}-${pad(one[4])}`;
      return one[1] === '시작일' ? { start: d, end: null, openEnd: true } : { start: d, end: d };
    }
    return null;
  };

  // 상세 페이지 전체 텍스트에서, 게시글 제목 직후 구간의 기간 표기를 찾음
  GC.periodFromDetail = function (html, title, refYear) {
    const text = GC.stripTags(html).replace(/\s+/g, ' ');
    const key = title.slice(0, 14);
    let i = text.indexOf(key);
    while (i >= 0) {
      const p = GC.guessPeriod(text.slice(i, i + 500), refYear);
      if (p) return p;
      i = text.indexOf(key, i + 1);
    }
    return null;
  };

  GC.INDIE_DEFAULTS = [
    { key: 'laika', name: '라이카시네마', theater: '라이카시네마 (연희동)', url: 'https://www.laikacinema.com/event', base: 'https://www.laikacinema.com/event', parser: 'imweb' }
  ];

  GC.fetchIndie = async function (ctx, sources) {
    const events = []; const errors = [];
    const year = new Date().getFullYear();
    const detailCache = ctx.cache.indieDetail || (ctx.cache.indieDetail = {});
    for (const src of sources || GC.INDIE_DEFAULTS) {
      try {
        const html = await ctx.get(src.url);
        let posts = [];
        if (src.parser === 'imweb' || /list-style-card/.test(html)) posts = GC.parseImwebBoard(html, src.base || src.url.replace(/\/$/, ''));
        else posts = GC.parseGenericList(html, src.url);
        for (const p of posts) {
          if (p.status === '종료' || p.status === '마감') continue;
          if (!GC.isGoodsEvent(p.title, false)) continue;
          let period = detailCache[p.url];
          if (period === undefined) {
            await ctx.sleep(400);
            try {
              const dh = await ctx.get(p.url);
              period = GC.periodFromDetail(dh, p.title, year);
            } catch (e) { period = null; }
            detailCache[p.url] = period;
          }
          const today = GC.todayStr();
          let start = period ? period.start : null, end = period ? period.end : null;
          // '소진 시까지' 이벤트: 진행중이면 오늘까지 이어지는 것으로 표시
          if (!start && p.status === '진행중') start = p.posted || today;
          if (start && !end) end = p.status === '진행예정' ? start : (today > start ? today : start);
          events.push({
            id: mkId('INDIE', src.key + '-' + (p.idx || p.url)), chain: 'INDIE', source: src.name, title: p.title,
            movie: GC.extractMovie(p.title),
            start, end, openEnd: !period || !!period.openEnd,
            dateGuessed: !period, statusText: p.status,
            url: p.url, image: p.image, branchOnly: src.theater || src.name,
            goods: [], stock: [], stockKind: 'none', stockOk: false, type: GC.classify(p.title, [])
          });
        }
      } catch (err) { errors.push(src.name + ': ' + (err.message || err)); }
    }
    return { events, errors };
  };

  // 사용자가 추가한 일반 웹페이지: 키워드가 들어간 링크 텍스트를 모음
  GC.parseGenericList = function (html, pageUrl) {
    const out = [];
    const origin = (pageUrl.match(/^https?:\/\/[^/]+/) || [''])[0];
    const re = /<a[^>]*href="([^"#][^"]*)"[^>]*>([\s\S]*?)<\/a>/g;
    let m; const seen = new Set();
    while ((m = re.exec(html))) {
      const text = GC.stripTags(m[2]).replace(/\s+/g, ' ').trim();
      if (text.length < 6 || text.length > 140) continue;
      let href = GC.decode(m[1]);
      if (href.startsWith('/')) href = origin + href;
      else if (!/^https?:/.test(href)) continue;
      if (seen.has(href)) continue;
      seen.add(href);
      const st = (text.match(/진행\s?예정|진행중|종료|마감/) || [])[0];
      out.push({ idx: null, title: text.replace(/진행\s?예정|진행중/, '').trim(), status: st ? st.replace(/\s/g, '') : null, url: href, image: null });
    }
    return out;
  };
})(typeof self !== 'undefined' ? self : globalThis);

