/* 영화굿즈 캘린더 — 상영시간표 모듈
 * 각 영화관 공식 시간표 API(사이트가 직접 쓰는 것)를 호출해 공통 형식으로 변환.
 * 행 형식: { chain, theaterId, theater, date, start, end, hall, format, remain, total, movie, pkg, bookable, url }
 */
(function (G) {
  const GC = G.GC || (G.GC = {});
  const pad = (n) => String(n).padStart(2, '0');
  const hhmm = (s) => { s = String(s || '').replace(':', ''); return s.length >= 3 ? `${pad(s.slice(0, s.length - 2))}:${s.slice(-2)}` : ''; };

  // ───────── 서울 지점 목록 (각 사이트에서 확인, 2026-10-31) ─────────
  GC.SEOUL = {
    MEGABOX: [['1372', '강남'], ['1341', '강동'], ['0090', '구의이스트폴'], ['1431', '군자'], ['0041', '더부티크목동현대백화점'], ['1572', '마곡'], ['1581', '목동'], ['1311', '상봉'], ['1211', '상암월드컵경기장'], ['1371', '센트럴'], ['1381', '송파파크하비오'], ['0099', '이수'], ['1351', '코엑스'], ['1212', '홍대(아니메)'], ['0083', '화곡']],
    LOTTE: [['1013', '가산디지털'], ['9094', '가양'], ['9010', '강동'], ['1004', '건대입구'], ['1009', '김포공항'], ['1003', '노원'], ['1023', '도곡'], ['1017', '독산'], ['1012', '서울대입구'], ['9099', '수락산'], ['9104', '수유'], ['1024', '신대방(구로디지털역)'], ['1015', '신도림'], ['1007', '신림'], ['1001', '에비뉴엘(명동)'], ['1002', '영등포'], ['1014', '용산'], ['1016', '월드타워'], ['1021', '은평(롯데몰)'], ['9083', '중랑'], ['1008', '청량리'], ['1005', '홍대입구']],
    CINEQ: [['1001', '신도림']],
    // 디트릭스(독립·예술영화관 예매 플랫폼) 서울 지점: [BrandCd, CinemaCd, 이름]
    DTRYX: [['etc', '000113', '낭만극장'], ['indieart', '000065', '더숲아트시네마'], ['spacedog', '000072', '라이카시네마'], ['seoulcc', '000160', '서울영화센터'], ['cinecube', '000003', '씨네큐브광화문'], ['etc', '000088', '아리랑시네센터'], ['etc', '000162', '아트나인'], ['indieart', '000067', '아트하우스모모'], ['indieart', '000069', '에무시네마'], ['etc', '000115', '허리우드클래식']]
  };
  GC.dtryxByName = function (name) {
    const k = String(name || '').replace(/\s|\(.*?\)/g, '');
    return GC.SEOUL.DTRYX.find(([, , n]) => k.includes(n.replace(/\s/g, '')) || n.replace(/\s/g, '').includes(k.replace(/광화문$/, '')));
  };

  // ───────── 영화명 정규화/매칭 ─────────
  GC.normMovie = function (name) {
    let s = GC.decode(String(name || ''));
    s = s.replace(/^\s*\[[^\]]*(굿즈|패키지|무대인사|GV|시사|상영회|특별)[^\]]*\]\s*/i, '');
    s = s.replace(/[(（][^)）]*(자막|더빙|무삭제|감독판|확장판|리마스터|재개봉|4K|HFR|ATMOS|IMAX|4DX|SCREENX|LED|돌비|굿즈|패키지)[^)）]*[)）]/gi, '');
    s = s.replace(/\s*[-–:]\s*/g, ' ');
    return s.toLowerCase().replace(/[^0-9a-z가-힣ぁ-んァ-ン一-龥]/g, '');
  };
  GC.movieMatch = function (a, b) {
    const x = GC.normMovie(a), y = GC.normMovie(b);
    if (!x || !y) return false;
    if (x === y) return true;
    const [s, l] = x.length <= y.length ? [x, y] : [y, x];
    return s.length >= 4 && l.startsWith(s);
  };

  // 이벤트 제목/굿즈명에 특정 포맷이 적혀 있으면 그 포맷 회차만 해당
  const FORMATS = [
    ['4DX', /4\s?DX/i], ['SCREENX', /SCREEN\s?X|스크린\s?X/i], ['IMAX', /IMAX|아이맥스/i], ['DOLBY', /DOLBY|돌비/i],
    ['MX4D', /MX4D/i], ['SUPER4D', /수퍼\s?4D|SUPER\s?4D/i], ['CHARLOTTE', /샤롯데|CHARLOTTE/i], ['SUPERPLEX', /수퍼플렉스|SUPERPLEX/i],
    ['LED', /\bLED\b|수퍼\s?LED|MEGA\s?\|?\s?LED/i], ['BOUTIQUE', /부티크|BOUTIQUE/i], ['GOLDCLASS', /골드클래스|GOLD\s?CLASS/i],
    ['ATMOS', /ATMOS|애트머스/i], ['SPHEREX', /SPHERE\s?X/i], ['ULTRA', /ULTRA\s?4DX|울트라/i]
  ];
  GC.requiredFormats = function (ev) {
    const t = [ev.title, ...(ev.goods || []).map((g) => g.name)].join(' ');
    const out = [];
    for (const [k, re] of FORMATS) if (re.test(t)) out.push(k);
    // "ULTRA 4DX"는 4DX를 포함하므로 4DX만 요구해도 충분
    return out.filter((k) => k !== 'ULTRA');
  };
  GC.formatOk = function (row, req) {
    if (!req || !req.length) return true;
    const raw = row.movieRaw || '';
    // "(non-IMAX)"처럼 특별관에서 일반 포맷으로 트는 회차는 그 포맷이 아님
    const negated = (k) => new RegExp('non[-\\s]?(' + FORMATS.find((f) => f[0] === k)[1].source + ')', 'i').test(raw);
    const s = `${row.hall} ${row.format} ${raw.replace(/non[-\s]?[a-z0-9]+/gi, '')}`;
    return req.some((k) => !negated(k) && FORMATS.find((f) => f[0] === k)[1].test(s));
  };

  // ───────── 체인별 시간표 호출 ─────────
  // theater: { id, name, brand? } , ymd: 'YYYY-MM-DD'
  GC.fetchSchedule = async function (ctx, chain, theater, ymd) {
    const d8 = ymd.replace(/-/g, '');
    if (chain === 'CGV') {
      const j = JSON.parse(await ctx.get(`https://cgv.co.kr/api/v1/booking/searchMovScnInfo?coCd=A420&siteNo=${theater.id}&scnYmd=${d8}&rtctlScopCd=08`));
      return (j.data || []).map((x) => ({
        chain, theaterId: theater.id, theater: 'CGV ' + (x.siteNm || theater.name).replace(/^CGV\s*/, ''), date: ymd,
        start: hhmm(x.scnsrtTm), end: hhmm(x.scnendTm), hall: x.expoScnsNm || x.scnsNm || '', format: [x.movkndDsplNm, x.sascnsGradNm !== '일반' ? x.sascnsGradNm : ''].filter(Boolean).join(' '),
        remain: num(x.frSeatCnt), total: num(x.stcnt), movie: x.movNm || x.expoProdNm || x.prodNm, movieRaw: x.prodNm,
        pkg: /패키지/.test(x.prodNm || ''), bookable: x.cntlYn !== 'Y',
        url: 'https://cgv.co.kr/cnm/movieBook/cinema'
      }));
    }
    if (chain === 'MEGABOX') {
      const txt = await ctx.postJSON('https://www.megabox.co.kr/on/oh/ohc/Brch/schedulePage.do', { masterType: 'brch', detailType: 'area', brchNo: theater.id, firstAt: 'N', brchNo1: theater.id, crtDe: GC.todayStr().replace(/-/g, ''), playDe: d8 });
      const m = (JSON.parse(txt).megaMap || {});
      if (m.playDe && m.playDe !== d8) return []; // 그 날짜 시간표 없음(사이트가 다른 날짜로 대체해 응답)
      return (m.movieFormList || []).map((x) => ({
        chain, theaterId: theater.id, theater: '메가박스 ' + (x.brchNm || theater.name), date: ymd,
        start: x.playStartTime, end: x.playEndTime, hall: GC.decode(x.theabExpoNm || ''), format: GC.decode(x.playKindNm || ''),
        remain: num(x.restSeatCnt), total: num(x.totSeatCnt), movie: GC.decode(x.rpstMovieNm || x.movieNm), movieRaw: GC.decode(x.movieNm),
        pkg: /패키지/.test((x.cttsTyDivCdNm || '') + (x.movieNm || '')), bookable: x.bokdAbleAt === 'Y',
        url: `https://www.megabox.co.kr/theater/time?brchNo=${theater.id}`
      }));
    }
    if (chain === 'LOTTE') {
      const p = { MethodName: 'GetPlaySequence', channelType: 'HO', osType: 'W', osVersion: 'Chrome', playDate: ymd, cinemaID: `1|0001|${theater.id}`, representationMovieCode: '' };
      const j = JSON.parse(await ctx.postForm('https://www.lottecinema.co.kr/LCWS/Ticketing/TicketingData.aspx', { paramList: JSON.stringify(p) }));
      return (((j.PlaySeqs || {}).Items) || []).filter((x) => !x.PlayDt || x.PlayDt === ymd).map((x) => ({
        chain, theaterId: theater.id, theater: '롯데시네마 ' + (x.CinemaNameKR || theater.name), date: ymd,
        start: x.StartTime, end: x.EndTime, hall: x.ScreenNameKR || '', format: [x.FilmNameKR, x.ScreenDivisionNameKR !== '일반' ? x.ScreenDivisionNameKR : '', x.FourDTypeNameKR].filter(Boolean).join(' '),
        remain: num(x.BookingSeatCount), total: num(x.TotalSeatCount), movie: x.MovieNameKR, movieRaw: x.MovieNameKR,
        pkg: /패키지/.test((x.MovieNameKR || '') + (x.SequenceNoGroupNameKR || '') + (x.AccompanyTypeNameKR || '')), bookable: x.IsBookingYN === 'Y',
        url: `https://www.lottecinema.co.kr/NLCHS/Cinema/Detail?divisionCode=1&detailDivisionCode=0001&cinemaID=${theater.id}`
      }));
    }
    if (chain === 'CINEQ') {
      const html = await ctx.postFormUrl('https://www.cineq.co.kr/Theater/MovieTable2', { TheaterCode: theater.id, PlayDate: d8 });
      return GC.parseCineQTable(html).map((x) => Object.assign(x, { chain, theaterId: theater.id, theater: '씨네Q ' + theater.name, date: ymd, url: `https://www.cineq.co.kr/Theater/Movie?TheaterCode=${theater.id}` }));
    }
    if (chain === 'DTRYX') {
      const j = JSON.parse(await ctx.get(`https://www.dtryx.com/cinema/showseq_list.do?BrandCd=${theater.brand}&CinemaCd=${theater.id}&PlaySDT=${ymd}`));
      return (j.Showseqlist || []).filter((x) => !x.PlaySDT || x.PlaySDT === ymd).map((x) => ({
        chain, theaterId: theater.id, theater: x.CinemaNm || theater.name, date: ymd,
        start: x.StartTime, end: x.EndTime, hall: x.ScreenNmNat || x.ScreenNm || '', format: x.ScreeningInfo || '',
        remain: num(x.RemainSeatCnt), total: num(x.TotalSeatCnt), movie: x.MovieNm, movieRaw: x.MovieNm,
        pkg: /^good/i.test(x.DisplayTypeDetail || '') || /굿즈/.test(x.ScreeningInfo || ''), special: x.DisplayTypeDetailNm ? String(x.DisplayTypeDetailNm).replace(/^#/, '') : '',
        bookable: true, url: `https://www.dtryx.com/cinema/main.do?BrandCd=${theater.brand}&CinemaCd=${theater.id}`
      }));
    }
    return [];
  };
  function num(v) { const n = Number(v); return isNaN(n) ? null : n; }

  GC.parseCineQTable = function (html) {
    const out = [];
    const blocks = html.split(/<div class="each-movie-time">/).slice(1);
    for (const b of blocks) {
      const rawTitle = ((b.match(/<div class="title">([\s\S]*?)<\/div>/) || [])[1] || '').replace(/<span class="rate[^"]*">[\s\S]*?<\/span>/g, '');
      const title = GC.stripTags(rawTitle).trim();
      const screens = b.split(/<div class="screen">/).slice(1);
      for (const s of screens) {
        const hall = GC.stripTags((s.match(/<div class="screen-name"[^>]*>([\s\S]*?)<\/div>/) || [])[1] || '').replace(/\s+/g, ' ').replace(/(\d+)\s+관/, '$1관').trim();
        const re = /<div class="time"[^>]*>\s*<a[^>]*>\s*([0-9]{1,2}:[0-9]{2})\s*<span class="to">\s*~\s*([0-9]{1,2}:[0-9]{2})\s*<\/span>\s*<span class="seats-status">\s*(\d+)\s*\/\s*(\d+)\s*<\/span>/g;
        let m;
        while ((m = re.exec(s))) out.push({ start: m[1].padStart(5, '0'), end: m[2].padStart(5, '0'), hall, format: '', remain: +m[3], total: +m[4], movie: title, movieRaw: title, pkg: /패키지/.test(title), bookable: true });
      }
    }
    return out;
  };

  // ───────── 이벤트 → 굿즈를 받을 수 있는 지점 목록 ─────────
  // 반환: [{ chain, id, name, brand?, level, count, goodsId, known }]
  GC.eventTheaters = function (ev) {
    const res = [];
    const add = (o) => { if (!res.find((r) => r.chain === o.chain && r.id === o.id && r.goodsId === o.goodsId)) res.push(o); };
    if (ev.chain === 'CGV' || ev.chain === 'MEGABOX' || ev.chain === 'LOTTE') {
      const prefix = { CGV: /^CGV\s*/, MEGABOX: /^메가박스\s*/, LOTTE: /^롯데시네마\s*/ }[ev.chain];
      for (const s of ev.stock || []) {
        let id = s.theaterId;
        const name = s.theater.replace(prefix, '');
        if (!id && GC.SEOUL[ev.chain]) { const f = GC.SEOUL[ev.chain].find(([, n]) => n === name); if (f) id = f[0]; }
        if (!id) continue;
        add({ chain: ev.chain, id, name, level: s.level, count: s.count, goodsId: s.goodsId, known: true });
      }
      if (!res.length && ev.chain !== 'CGV' && !(ev.goods || []).length) {
        // 지점별 재고 미공개 이벤트: 서울 전 지점(배부 지점 제한 여부는 공지 확인 필요)
        for (const [id, name] of GC.SEOUL[ev.chain]) add({ chain: ev.chain, id, name, level: 'unknown', known: false });
      }
    } else if (ev.chain === 'CINEQ') {
      for (const [id, name] of GC.SEOUL.CINEQ) add({ chain: 'CINEQ', id, name, level: 'unknown', known: false });
    } else if (ev.chain === 'CINECUBE') {
      const d = GC.SEOUL.DTRYX.find((x) => x[1] === '000003');
      add({ chain: 'DTRYX', id: d[1], brand: d[0], name: d[2], level: ev.allOut ? 'out' : 'unknown', known: false });
    } else if (ev.chain === 'INDIE') {
      const d = GC.dtryxByName(ev.branchOnly || ev.source);
      if (d) add({ chain: 'DTRYX', id: d[1], brand: d[0], name: d[2], level: 'unknown', known: false });
    } else if (ev.chain === 'DTRYX') {
      const d = GC.SEOUL.DTRYX.find((x) => x[1] === ev.cinemaCd);
      if (d) add({ chain: 'DTRYX', id: d[1], brand: d[0], name: d[2], level: (ev.stock[0] || {}).level || 'unknown', count: (ev.stock[0] || {}).count, known: true });
    }
    return res;
  };

  // 시간표 행이 이 이벤트의 굿즈 대상 회차인지
  GC.rowMatchesEvent = function (row, ev) {
    if (ev.chain === 'DTRYX') return row.pkg && GC.movieMatch(row.movie, ev.movie);
    const mv = ev.movie || GC.extractMovie(ev.title);
    if (!mv) return false;
    if (!GC.movieMatch(row.movie, mv) && !GC.movieMatch(row.movieRaw, mv)) return false;
    if (!GC.formatOk(row, GC.requiredFormats(ev))) return false;
    if (ev.type === '굿즈패키지') return row.pkg;
    return true;
  };

  // ───────── 디트릭스 굿즈패키지 회차 수집 → 이벤트 ─────────
  GC.fetchDtryx = async function (ctx, opts) {
    opts = opts || {};
    const days = opts.days || 14;
    const errors = []; const groups = {};
    const today = GC.todayStr();
    const now = new Date();
    const nowHM = `${pad(now.getHours())}:${pad(now.getMinutes())}`;
    for (const [brand, code, name] of GC.SEOUL.DTRYX) {
      let empty = 0;
      for (let i = 0; i < days; i++) {
        const d = new Date(); d.setDate(d.getDate() + i);
        const ymd = GC.todayStr(d);
        let rows;
        try { rows = await GC.fetchSchedule(ctx, 'DTRYX', { id: code, brand, name }, ymd); }
        catch (e) { if (e && e.rateLimited) throw e; errors.push(`${name} ${ymd}: ${e.message || e}`); rows = []; }
        await ctx.sleep(opts.delay ?? 200);
        if (!rows.length) { if (++empty >= 4 && i >= 6) break; continue; }
        empty = 0;
        for (const r of rows) {
          if (!r.pkg) continue;
          const k = code + '|' + GC.normMovie(r.movie);
          const g = groups[k] || (groups[k] = { code, brand, name, movie: r.movie, sessions: [] });
          g.sessions.push({ date: r.date, start: r.start, end: r.end, hall: r.hall, format: r.format, remain: r.remain, total: r.total });
        }
      }
    }
    const events = [];
    for (const [k, g] of Object.entries(groups)) {
      g.sessions.sort((a, b) => (a.date + a.start).localeCompare(b.date + b.start));
      const future = g.sessions.filter((s) => s.date > today || (s.date === today && s.start >= nowHM));
      const remain = future.reduce((a, s) => a + (s.remain || 0), 0);
      const level = !future.length ? 'out' : remain <= 0 ? 'out' : remain <= 10 ? 'few' : remain <= 40 ? 'some' : 'plenty';
      const id = 'DTRYX:' + g.code + '-' + GC.normMovie(g.movie).slice(0, 40);
      events.push({
        id, chain: 'DTRYX', source: g.name, cinemaCd: g.code, brand: g.brand,
        title: `<${g.movie}> 굿즈패키지 상영 · ${g.name}`, movie: g.movie,
        start: g.sessions[0].date, end: g.sessions[g.sessions.length - 1].date,
        url: `https://www.dtryx.com/cinema/main.do?BrandCd=${g.brand}&CinemaCd=${g.code}`, image: null,
        branchOnly: g.name + ' (디트릭스 예매)',
        goods: [{ id: 'pkg', name: '굿즈패키지 (관람권+굿즈)', desc: '구성품은 극장 공지(인스타그램 등)에 안내됩니다. 남은 수량 = 굿즈패키지 회차 잔여석.' }],
        stock: [{ goodsId: 'pkg', theater: g.name, theaterId: g.code, count: remain, level }],
        stockKind: 'count', stockOk: true, sessions: g.sessions, type: '굿즈패키지'
      });
    }
    return { events, errors };
  };
})(typeof self !== 'undefined' ? self : globalThis);

site/calendar.css.text:
:root {
  --bg: #f6f5f2; --panel: #ffffff; --ink: #1d1d1f; --ink2: #5f6368; --ink3: #9aa0a6; --line: #e6e3dc;
  --accent: #1d1d1f; --hot: #e5484d; --warm: #f08c00; --cool: #2f9e44;
  --CGV: #e03a2f; --MEGABOX: #5b3fb0; --LOTTE: #f07a1a; --CINEQ: #0f8b8d; --CINECUBE: #2b6cb0; --DTRYX: #b2467f; --INDIE: #6b7c3a;
  --plenty: #2f9e44; --some: #f2b705; --few: #f0661f; --out: #c4c4c4; --ready: #8ec5ff; --unknown: #dcdcdc;
  --r: 12px;
  font-family: Pretendard, "Apple SD Gothic Neo", "Malgun Gothic", system-ui, sans-serif;
}
* { box-sizing: border-box; }
body { margin: 0; background: var(--bg); color: var(--ink); font-size: 14px; }
button { font: inherit; }
.hidden { display: none !important; }

.top { position: sticky; top: 0; z-index: 20; display: flex; gap: 16px; align-items: center; padding: 12px 20px; background: rgba(246,245,242,.92); backdrop-filter: blur(8px); border-bottom: 1px solid var(--line); }
.brand { display: flex; gap: 10px; align-items: center; min-width: 230px; }
.logo { width: 36px; height: 36px; border-radius: 10px; background: var(--ink); color: #fff; display: grid; place-items: center; font-weight: 800; }
h1 { font-size: 17px; margin: 0; letter-spacing: -.3px; }
.sub { margin: 2px 0 0; color: var(--ink2); font-size: 12px; }
.views { display: flex; background: #ebe8e1; border-radius: 10px; padding: 3px; }
.view-btn { border: 0; background: none; padding: 7px 16px; border-radius: 8px; cursor: pointer; color: var(--ink2); font-weight: 600; }
.view-btn.on { background: #fff; color: var(--ink); box-shadow: 0 1px 2px rgba(0,0,0,.08); }
.top-right { margin-left: auto; display: flex; gap: 8px; align-items: center; }
#search { width: 240px; padding: 8px 12px; border: 1px solid var(--line); border-radius: 10px; background: #fff; }
.btn { border: 1px solid var(--line); background: #fff; padding: 7px 12px; border-radius: 10px; cursor: pointer; color: var(--ink); }
.btn:hover { border-color: #cfcac0; }
.btn.primary { background: var(--ink); color: #fff; border-color: var(--ink); }
.btn.primary[disabled] { opacity: .6; cursor: progress; }
.btn.icon { width: 34px; height: 34px; padding: 0; display: grid; place-items: center; }
.btn.small { padding: 4px 10px; font-size: 12px; }
.btn.danger { color: #c92a2a; }

.sources { display: flex; flex-wrap: wrap; gap: 6px; padding: 10px 20px 0; }
.src { display: inline-flex; align-items: center; gap: 6px; font-size: 12px; color: var(--ink2); background: #fff; border: 1px solid var(--line); border-radius: 999px; padding: 4px 10px; }
.src i { width: 8px; height: 8px; border-radius: 50%; background: var(--ink3); }
.src.ok i { background: var(--plenty); } .src.stale i { background: var(--some); } .src.err i { background: var(--hot); } .src.run i { background: #4dabf7; animation: pulse 1s infinite; }
@keyframes pulse { 50% { opacity: .3; } }

.filters { display: flex; flex-wrap: wrap; gap: 10px 16px; align-items: center; padding: 10px 20px; }
.chips { display: flex; flex-wrap: wrap; gap: 6px; }
.chip { border: 1px solid var(--line); background: #fff; border-radius: 999px; padding: 5px 11px; font-size: 12px; cursor: pointer; color: var(--ink2); display: inline-flex; gap: 6px; align-items: center; }
.chip .dot { width: 8px; height: 8px; }
.chip.on { background: var(--ink); border-color: var(--ink); color: #fff; }
.tg { font-size: 12px; color: var(--ink2); display: inline-flex; gap: 5px; align-items: center; cursor: pointer; }
.dot { display: inline-block; width: 7px; height: 7px; border-radius: 50%; }

.view-date { display: grid; grid-template-columns: minmax(380px, 470px) 1fr; gap: 18px; padding: 0 20px 20px; align-items: start; }
@media (max-width: 960px) { .view-date { grid-template-columns: 1fr; } .top { flex-wrap: wrap; } #search { width: 160px; } }
.cal-wrap { background: var(--panel); border: 1px solid var(--line); border-radius: var(--r); padding: 14px; position: sticky; top: 76px; }
.cal-head { display: flex; align-items: center; gap: 8px; margin-bottom: 8px; }
.cal-head h2 { margin: 0 auto 0 4px; font-size: 18px; letter-spacing: -.3px; order: -1; }
.cal-grid { display: grid; grid-template-columns: repeat(7, 1fr); gap: 4px; }
.cal-grid.dow span { text-align: center; font-size: 11px; color: var(--ink3); padding: 4px 0; }
.cal-grid.dow span:first-child { color: #e5484d; } .cal-grid.dow span:last-child { color: #3b82f6; }
.day { border: 1px solid transparent; border-radius: 10px; min-height: 64px; padding: 5px 6px; cursor: pointer; background: #faf9f6; display: flex; flex-direction: column; gap: 3px; position: relative; }
.day:hover { border-color: var(--line); }
.day.other { opacity: .35; }
.day.today .num { background: var(--ink); color: #fff; }
.day.sel { border-color: var(--ink); background: #fff; box-shadow: 0 0 0 1px var(--ink) inset; }
.day .num { font-size: 12px; font-weight: 700; width: 22px; height: 22px; border-radius: 50%; display: grid; place-items: center; }
.day.sun .num { color: #e5484d; } .day.sat .num { color: #3b82f6; } .day.today.sun .num, .day.today.sat .num { color: #fff; }
.day .cnt { font-size: 11px; color: var(--ink2); }
.day .dots { display: flex; flex-wrap: wrap; gap: 2px; max-width: calc(100% - 20px); }
.day .dots .dot { width: 6px; height: 6px; }
.day .new { position: absolute; top: 6px; right: 6px; font-size: 9px; font-weight: 700; color: var(--MEGABOX); }
.day .pill { position: absolute; bottom: 5px; right: 5px; }
.legend { display: flex; flex-wrap: wrap; gap: 4px 10px; font-size: 11px; color: var(--ink2); margin-top: 10px; }
.legend span { display: inline-flex; gap: 4px; align-items: center; }

.pill { display: inline-flex; align-items: center; gap: 4px; border-radius: 999px; padding: 2px 8px; font-size: 11px; font-weight: 700; white-space: nowrap; }
.pill.mini { padding: 0 5px; font-size: 10px; font-style: normal; }
.pill.hot { background: #ffe3e3; color: #c92a2a; } .pill.warm { background: #fff0d6; color: #b35900; } .pill.cool { background: #e6f6ea; color: #2b8a3e; }
.pill.gray { background: #f1f3f5; color: var(--ink2); }

.day-head { display: flex; align-items: baseline; gap: 10px; flex-wrap: wrap; margin: 4px 0 10px; }
.day-head h2 { margin: 0; font-size: 20px; letter-spacing: -.4px; }
.day-head .meta { color: var(--ink2); font-size: 13px; }
.group-title { font-size: 12px; font-weight: 700; color: var(--ink2); margin: 16px 0 8px; letter-spacing: .2px; }
.list { display: flex; flex-direction: column; gap: 8px; }
.empty { padding: 40px; text-align: center; color: var(--ink3); background: var(--panel); border: 1px dashed var(--line); border-radius: var(--r); }

.card { display: grid; grid-template-columns: 4px 64px 1fr auto; gap: 12px; background: var(--panel); border: 1px solid var(--line); border-radius: var(--r); padding: 10px 12px 10px 0; cursor: pointer; overflow: hidden; }
.card:hover { border-color: #cfcac0; box-shadow: 0 2px 10px rgba(0,0,0,.04); }
.card .bar { border-radius: 0 4px 4px 0; }
.card .thumb { width: 64px; height: 64px; border-radius: 8px; background: #efece6 center/cover no-repeat; align-self: center; margin-left: 4px; }
.card .body { min-width: 0; display: flex; flex-direction: column; gap: 4px; }
.card .row1 { display: flex; gap: 6px; flex-wrap: wrap; align-items: center; font-size: 11px; }
.badge { font-size: 11px; font-weight: 700; border-radius: 6px; padding: 1px 6px; color: #fff; }
.tbadge { font-size: 11px; border-radius: 6px; padding: 1px 6px; background: #f1efe9; color: var(--ink2); }
.tbadge.pkg { background: #efe7ff; color: #5b3fb0; font-weight: 700; }
.period { color: var(--ink2); }
.period b { color: var(--hot); }
.card .title { font-weight: 700; font-size: 14px; line-height: 1.35; overflow: hidden; text-overflow: ellipsis; display: -webkit-box; -webkit-line-clamp: 2; -webkit-box-orient: vertical; }
.card .goods { font-size: 12px; color: var(--ink2); overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.card .side { display: flex; flex-direction: column; align-items: flex-end; gap: 6px; justify-content: space-between; }
.star { border: 0; background: none; font-size: 18px; cursor: pointer; color: #ced4da; padding: 0; line-height: 1; }
.star.on { color: #f59f00; }
.stockline { display: flex; align-items: center; gap: 8px; font-size: 11px; color: var(--ink2); flex-wrap: wrap; }
.sbar { display: flex; width: 120px; height: 7px; border-radius: 4px; overflow: hidden; background: #eee; }
.sbar i { display: block; height: 100%; }
.lv-plenty { background: var(--plenty); } .lv-some { background: var(--some); } .lv-few { background: var(--few); } .lv-out { background: var(--out); } .lv-ready { background: var(--ready); } .lv-unknown { background: var(--unknown); }

/* 영화별 */
.view-movie { padding: 0 20px 20px; }
.movie-axis-note { font-size: 11px; color: var(--ink3); margin: 0 0 8px; }
.mgroup { background: var(--panel); border: 1px solid var(--line); border-radius: var(--r); margin-bottom: 12px; overflow: hidden; }
.mhead { display: flex; gap: 12px; align-items: center; padding: 12px 14px; cursor: pointer; }
.mhead .thumb { width: 44px; height: 44px; border-radius: 8px; background: #efece6 center/cover; flex: none; }
.mhead h3 { margin: 0; font-size: 15px; }
.mhead .meta { font-size: 12px; color: var(--ink2); display: flex; gap: 6px; align-items: center; flex-wrap: wrap; margin-top: 3px; }
.mhead .caret { margin-left: auto; color: var(--ink3); }
.timeline { padding: 4px 14px 14px; }
.axis, .trow { display: grid; grid-template-columns: 240px 1fr; align-items: center; gap: 10px; }
.axis .ticks { position: relative; height: 20px; font-size: 10px; color: var(--ink3); }
.axis .ticks span { position: absolute; transform: translateX(-50%); }
.trow { min-height: 30px; cursor: pointer; border-top: 1px solid #f1efe9; }
.trow:hover { background: #faf9f6; }
.trow .lbl { font-size: 12px; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; display: flex; gap: 6px; align-items: center; }
.track { position: relative; height: 30px; }
.track .seg { position: absolute; top: 8px; height: 14px; border-radius: 7px; opacity: .9; }
.track .seg.open { background-image: repeating-linear-gradient(45deg, rgba(255,255,255,.35) 0 4px, transparent 4px 8px); }
.track .todayline { position: absolute; top: 0; bottom: 0; width: 2px; background: var(--hot); opacity: .6; }
.track .hotdot { position: absolute; top: 6px; width: 18px; height: 18px; border-radius: 50%; background: var(--hot); color: #fff; font-size: 10px; display: grid; place-items: center; font-weight: 800; }

/* 상세 드로어 */
.scrim { position: fixed; inset: 0; background: rgba(0,0,0,.25); z-index: 30; }
.drawer { position: fixed; top: 0; right: 0; bottom: 0; width: min(560px, 100vw); background: #fff; z-index: 40; box-shadow: -8px 0 30px rgba(0,0,0,.12); overflow-y: auto; }
.drawer-inner { padding: 20px 22px 40px; position: relative; }
.drawer .close { position: absolute; top: 14px; right: 14px; }
.d-hero { display: grid; grid-template-columns: 96px 1fr; gap: 14px; margin-right: 40px; }
.d-hero .thumb { width: 96px; height: 128px; border-radius: 10px; background: #efece6 center/cover; }
.d-title { font-size: 18px; font-weight: 800; letter-spacing: -.3px; margin: 6px 0; line-height: 1.35; }
.d-meta { font-size: 12px; color: var(--ink2); display: flex; flex-direction: column; gap: 3px; }
.d-actions { display: flex; gap: 8px; margin: 14px 0; flex-wrap: wrap; }
.d-actions a { text-decoration: none; }
.sect { margin-top: 18px; }
.sect h4 { font-size: 13px; margin: 0 0 8px; display: flex; align-items: center; gap: 8px; }
.goods-item { border: 1px solid var(--line); border-radius: 10px; padding: 10px 12px; margin-bottom: 10px; }
.goods-item .gname { font-weight: 700; }
.goods-item .gdesc { font-size: 12px; color: var(--ink2); white-space: pre-wrap; margin-top: 4px; }
.predict-box { border-radius: 10px; padding: 10px 12px; font-size: 12px; margin: 10px 0; }
.predict-box.hot { background: #fff5f5; border: 1px solid #ffc9c9; }
.predict-box.warm { background: #fff9eb; border: 1px solid #ffe08a; }
.predict-box.cool { background: #f3fbf5; border: 1px solid #c3ebcd; }
.predict-box.none { background: #f8f9fa; border: 1px solid var(--line); color: var(--ink2); }
.predict-box b { font-size: 13px; }
table.st { width: 100%; border-collapse: collapse; font-size: 12px; margin-top: 8px; }
table.st th { text-align: left; color: var(--ink3); font-weight: 600; padding: 4px 6px; border-bottom: 1px solid var(--line); }
table.st td { padding: 6px; border-bottom: 1px solid #f3f1ec; vertical-align: middle; }
table.st td.num { text-align: right; font-variant-numeric: tabular-nums; }
.lvchip { display: inline-flex; gap: 5px; align-items: center; font-weight: 600; }
.lvchip i { width: 8px; height: 8px; border-radius: 50%; display: inline-block; }
.spark { vertical-align: middle; }
.note { font-size: 12px; color: var(--ink2); background: #faf9f6; border-radius: 8px; padding: 8px 10px; white-space: pre-wrap; }
.muted { color: var(--ink3); }

dialog { border: 0; border-radius: 16px; padding: 0; width: min(720px, 94vw); box-shadow: 0 20px 60px rgba(0,0,0,.2); }
dialog::backdrop { background: rgba(0,0,0,.3); }
.settings { padding: 22px 24px; display: flex; flex-direction: column; gap: 8px; }
.settings h2 { margin: 0 0 6px; font-size: 18px; }
.settings h3 { margin: 14px 0 4px; font-size: 13px; }
.hint { font-size: 12px; color: var(--ink2); margin: 0; }
.diag { width: 100%; border-collapse: collapse; font-size: 12px; }
.diag td, .diag th { padding: 5px 6px; border-bottom: 1px solid #f1efe9; text-align: left; vertical-align: top; }
.diag .err { color: #c92a2a; }
.src-settings { display: grid; grid-template-columns: repeat(3, 1fr); gap: 6px 14px; font-size: 12px; }
.src-settings label { display: flex; align-items: center; gap: 6px; }
.src-settings input[type=number] { width: 56px; padding: 3px 5px; border: 1px solid var(--line); border-radius: 6px; }
.indie-row { display: flex; gap: 8px; align-items: center; font-size: 12px; padding: 4px 0; }
.indie-row span.url { color: var(--ink3); overflow: hidden; text-overflow: ellipsis; white-space: nowrap; flex: 1; }
.indie-add { display: flex; gap: 6px; }
.indie-add input { padding: 6px 8px; border: 1px solid var(--line); border-radius: 8px; }
.indie-add input:nth-child(2) { flex: 1; }
.settings-actions { display: flex; gap: 8px; margin-top: 16px; }
.grow { flex: 1; }
.foot { padding: 10px 20px 30px; font-size: 11px; color: var(--ink3); line-height: 1.6; max-width: 1100px; }

/* 상영 시간표 */
.mhead .stbtn { margin-left: auto; white-space: nowrap; }
.mhead .caret { display: none; }
.stpanel { border: 1px solid var(--line); border-radius: 12px; padding: 12px; background: #fcfbf8; }
.stdates { display: flex; gap: 5px; overflow-x: auto; padding-bottom: 4px; }
.stdates .chip { flex: none; } .stdates .chip small { opacity: .7; margin-left: 2px; }
.sttools { display: flex; gap: 10px; align-items: center; flex-wrap: wrap; margin: 8px 0; font-size: 12px; }
.stnext { font-size: 12px; background: #e7f5ff; color: #1864ab; border-radius: 8px; padding: 6px 10px; margin-bottom: 8px; }
.stpanel .hint { margin: 4px 0; font-size: 11px; }
.stpanel .hint.err { color: #c92a2a; }
.stlist { display: flex; flex-direction: column; gap: 4px; margin-top: 6px; }
.strow { display: grid; grid-template-columns: 56px minmax(0, 1.25fr) 64px minmax(0, 1fr) 46px; gap: 8px; align-items: center; background: #fff; border: 1px solid #efece6; border-radius: 9px; padding: 7px 9px; font-size: 12px; }
.strow.past { opacity: .45; }
.strow.sold .st-time b { text-decoration: line-through; color: var(--ink3); }
.st-time b { font-size: 15px; font-variant-numeric: tabular-nums; display: block; }
.st-time small, .st-where small, .st-seat small { color: var(--ink3); }
.st-where small { display: block; margin-top: 2px; }
.st-where .badge { font-size: 10px; }
.st-seat { text-align: right; font-variant-numeric: tabular-nums; }
.soldtxt { color: #c92a2a; }
.st-goods { display: flex; flex-direction: column; gap: 3px; align-items: stretch; min-width: 0; }
.st-where b { word-break: keep-all; }
.gchip { display: flex; flex-wrap: wrap; gap: 2px 5px; align-items: center; background: #f6f5f2; border-radius: 6px; padding: 2px 6px; cursor: pointer; font-size: 11px; min-width: 0; }
.gchip:hover { background: #eceae4; }
.gchip .glabel { max-width: 100%; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; color: var(--ink2); }
.gchip .lvchip { white-space: nowrap; }
.strow .btn.small { padding: 4px 4px; text-decoration: none; text-align: center; white-space: nowrap; font-size: 11px; }

