/* 영화굿즈 캘린더 — 화면 */
const GC = window.GC;
const CHAINS = { CGV: 'CGV', MEGABOX: '메가박스', LOTTE: '롯데시네마', CINEQ: '씨네Q', CINECUBE: '씨네큐브', DTRYX: '디트릭스', INDIE: '독립영화관' };
const SCHAIN = { CGV: 'CGV', MEGABOX: '메가박스', LOTTE: '롯데', CINEQ: '씨네Q', DTRYX: '디트릭스' };
const TYPES = ['현장 증정', '굿즈패키지', '스페셜 티켓·카드', '상영회 증정', '굿즈 판매'];
const LV_ORDER = ['plenty', 'some', 'few', 'out', 'ready', 'unknown'];
const WD = ['일', '월', '화', '수', '목', '금', '토'];

const S = {
  events: {}, history: {}, learn: {}, meta: {}, settings: null, watch: {},
  view: 'date', sel: GC.todayStr(), month: null,
  chains: new Set(Object.keys(CHAINS)), types: new Set(TYPES.filter((t) => t !== '굿즈 판매')),
  q: '', fStock: false, fHot: false, fWatch: false, openId: null, preds: {}
};
const $ = (s, el = document) => el.querySelector(s);
const esc = (s) => String(s ?? '').replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
const today = () => GC.todayStr();
function parseYmd(s) { const [y, m, d] = s.split('-').map(Number); return new Date(y, m - 1, d); }
function addDays(ymd, n) { const d = parseYmd(ymd); d.setDate(d.getDate() + n); return GC.todayStr(d); }
function diffDays(a, b) { return Math.round((parseYmd(b) - parseYmd(a)) / 86400000); }
function md(ymd) { if (!ymd) return '?'; const d = parseYmd(ymd); return `${d.getMonth() + 1}.${d.getDate()}(${WD[d.getDay()]})`; }
function hm(ts) { const d = new Date(ts); return `${String(d.getHours()).padStart(2, '0')}:${String(d.getMinutes()).padStart(2, '0')}`; }
function ago(ts) {
  if (!ts) return '—';
  const m = Math.round((Date.now() - ts) / 60000);
  if (m < 1) return '방금'; if (m < 60) return m + '분 전';
  const h = Math.round(m / 60); if (h < 24) return h + '시간 전';
  return Math.round(h / 24) + '일 전';
}
function etaText(ts) {
  if (!ts) return '—';
  const d = new Date(ts); const t = today(); const dy = GC.todayStr(d);
  const dd = diffDays(t, dy);
  const pre = dd === 0 ? '오늘' : dd === 1 ? '내일' : dd > 1 ? `${dd}일 뒤` : '곧';
  return `${pre} ${hm(ts)}경`;
}

// ───────── 데이터 ─────────
async function load() {
  const d = await chrome.storage.local.get(['events', 'history', 'learn', 'meta', 'settings', 'watch', 'lastRefresh']);
  S.events = d.events || {}; S.history = d.history || {}; S.learn = d.learn || {}; S.meta = d.meta || {};
  S.settings = d.settings || null; S.watch = d.watch || {}; S.lastRefresh = d.lastRefresh;
  S.preds = {};
  for (const ev of Object.values(S.events)) S.preds[ev.id] = GC.predictEvent(ev, S.history, S.learn);
  render();
}
let loadTimer = null;
chrome.storage.onChanged.addListener((ch, area) => {
  if (area !== 'local') return;
  clearTimeout(loadTimer); loadTimer = setTimeout(load, 250);
});

function activeOn(ev, ymd) { return ev.start && ev.start <= ymd && (ev.end || ev.start) >= ymd; }
function hotProb(ev) { const p = S.preds[ev.id]; return p && p.best ? p.best.maxProb : null; }
function stockSummary(ev) {
  const c = { plenty: 0, some: 0, few: 0, out: 0, ready: 0, unknown: 0 }; let sum = 0, hasCount = false;
  for (const s of ev.stock || []) { c[s.level] = (c[s.level] || 0) + 1; if (s.count != null) { sum += Math.max(0, s.count); hasCount = true; } }
  const total = (ev.stock || []).length;
  return { c, total, sum, hasCount, avail: c.plenty + c.some + c.few };
}
function passes(ev) {
  if (!S.chains.has(ev.chain)) return false;
  if (!S.types.has(ev.type)) return false;
  if (S.fWatch && !S.watch[ev.id]) return false;
  if (S.fStock) { const s = stockSummary(ev); if (!s.avail) return false; }
  if (S.fHot) { const p = hotProb(ev); if (!(p >= 0.75)) return false; }
  if (S.q) {
    const hay = [ev.title, ev.movie, ev.source, ev.branchOnly, ...(ev.goods || []).map((g) => g.name), ...(ev.stock || []).map((s) => s.theater)].join(' ').toLowerCase();
    if (!S.q.split(/\s+/).every((w) => hay.includes(w))) return false;
  }
  return true;
}
const visible = () => Object.values(S.events).filter(passes);

// ───────── 공통 렌더 조각 ─────────
function chainBadge(ev) { return `<span class="badge" style="background:var(--${ev.chain})">${esc(CHAINS[ev.chain] || ev.source)}</span>`; }
function typeBadge(ev) { return `<span class="tbadge ${ev.type === '굿즈패키지' ? 'pkg' : ''}">${esc(ev.type)}</span>`; }
function periodText(ev, ref) {
  const t = today();
  let s = `${md(ev.start)} ~ ${ev.openEnd ? '소진 시' : md(ev.end)}`;
  if (!ev.openEnd && ev.end) {
    const left = diffDays(t, ev.end);
    if (left === 0) s += ' · <b>오늘 마감</b>';
    else if (left > 0 && left <= 7 && ev.start <= t) s += ` · D-${left}`;
  }
  if (ev.start > t) s += ` · ${diffDays(t, ev.start)}일 뒤 시작`;
  if (ev.dateGuessed) s += ' · <span class="muted">기간 추정</span>';
  return s;
}
function stockLine(ev) {
  if (ev.stockKind === 'none') return `<div class="stockline muted">재고 비공개 · ${esc(ev.branchOnly || '')}</div>`;
  if ((ev.stock || []).length && ev.stock.every((x) => x.level === 'out')) return `<div class="stockline"><span class="sbar"><i class="lv-out" style="width:100%"></i></span><span class="pill gray">서울 전 지점 소진</span></div>`;
  if (ev.allOut && !(ev.stock || []).length) return `<div class="stockline"><span class="pill gray">${esc(ev.allOutNote || '전 지점 소진')}</span></div>`;
  const s = stockSummary(ev);
  if (!s.total) return `<div class="stockline muted">${ev.goods && ev.goods.length ? '서울 지점 재고 정보 대기' : '지점별 재고 미공개(배부 시작 전일 수 있음)'}</div>`;
  const bar = LV_ORDER.filter((l) => s.c[l]).map((l) => `<i class="lv-${l}" style="width:${(s.c[l] / s.total) * 100}%"></i>`).join('');
  const parts = [];
  if (s.c.plenty) parts.push(`여유 ${s.c.plenty}`); if (s.c.some) parts.push(`소진 중 ${s.c.some}`);
  if (s.c.few) parts.push(`임박 ${s.c.few}`); if (s.c.out) parts.push(`소진 ${s.c.out}`); if (s.c.ready) parts.push(`준비중 ${s.c.ready}`);
