  const t = today();
  let html = '';
  for (let i = 0; i < 42; i++) {
    const d = new Date(startD); d.setDate(startD.getDate() + i);
    const ymd = GC.todayStr(d);
    if (i >= 35 && d.getMonth() !== m) break;
    const evs = list.filter((e) => activeOn(e, ymd));
    const chains = [...new Set(evs.map((e) => e.chain))];
    const starts = evs.filter((e) => e.start === ymd).length;
    const hot = ymd === t ? evs.filter((e) => hotProb(e) >= 0.75).length : 0;
    const cls = ['day', d.getMonth() !== m ? 'other' : '', ymd === t ? 'today' : '', ymd === S.sel ? 'sel' : '', d.getDay() === 0 ? 'sun' : '', d.getDay() === 6 ? 'sat' : ''].join(' ');
