function renderDay(list) {
  const t = today();
  const sel = S.sel;
  const evs = list.filter((e) => activeOn(e, sel));
  const undated = sel === t ? list.filter((e) => !e.start) : [];
  const d = parseYmd(sel);
  const hot = sel === t ? evs.filter((e) => hotProb(e) >= 0.45) : [];
  const hotIds = new Set(hot.map((e) => e.id));
  const starting = evs.filter((e) => e.start === sel && !hotIds.has(e.id));
  const ending = evs.filter((e) => e.end === sel && e.start !== sel && !e.openEnd && !hotIds.has(e.id));
  const rest = evs.filter((e) => !hotIds.has(e.id) && e.start !== sel && !(e.end === sel && !e.openEnd));
  const sortFn = (a, b) => (hotProb(b) ?? -1) - (hotProb(a) ?? -1) || (stockSummary(b).avail - stockSummary(a).avail) || a.title.localeCompare(b.title, 'ko');
  [hot, starting, ending, rest].forEach((g) => g.sort(sortFn));
