function spark(points) {
  const p = points.filter((x) => x[2] != null);
  if (p.length < 2) return '';
  const w = 90, h = 22; const t0 = p[0][0], t1 = Math.max(p[p.length - 1][3] || p[p.length - 1][0], Date.now());
  const max = Math.max(...p.map((x) => x[2]), 1);
  const pts = p.map((x) => `${((x[0] - t0) / (t1 - t0 || 1)) * w},${h - (x[2] / max) * (h - 2) - 1}`);
  pts.push(`${w},${h - (p[p.length - 1][2] / max) * (h - 2) - 1}`);
  return `<svg class="spark" width="${w}" height="${h}"><polyline fill="none" stroke="#f07a1a" stroke-width="1.5" points="${pts.join(' ')}"/></svg>`;
}
