// ───────── 굿즈 받을 수 있는 상영 시간표 ─────────
const ST = { cur: null };
const pad2 = (n) => String(n).padStart(2, '0');
function nowHMs() { const d = new Date(); return pad2(d.getHours()) + ':' + pad2(d.getMinutes()); }
// 영화관 영업일: 새벽(0~6시)은 전날 영업일의 심야 회차(24:xx, 25:xx)로 표기됨
function bizToday() { return new Date().getHours() < 6 ? addDays(today(), -1) : today(); }
function nowCmpFor(date) {
  const d = new Date(); const hm = pad2(d.getHours()) + ':' + pad2(d.getMinutes());
  if (date === today()) return hm;
  if (date === addDays(today(), -1) && d.getHours() < 6) return pad2(d.getHours() + 24) + ':' + pad2(d.getMinutes());
  return null; // 미래 날짜
}
function stDates(evs) {
  if (window.GC_DATA) {
    const b = bizToday();
    return (GC_DATA.dates || []).filter((d) => d >= b && evs.some((ev) => activeOn(ev, d) || (ev.openEnd && ev.start && ev.start <= d)));
  }
  const t = bizToday(), max = addDays(today(), 13); const set = new Set();
  for (const ev of evs) {
    let s = ev.start || t, e = ev.openEnd ? addDays(t, 6) : (ev.end || s);
    if (s < t) s = t; if (e > max) e = max;
    for (let d = s, i = 0; d <= e && i < 40; d = addDays(d, 1), i++) set.add(d);
  }
  return [...set].sort();
}
function goodsLabel(ev, goodsId) {
  const g = (ev.goods || []).find((x) => x.id === goodsId) || (ev.goods || [])[0];
  if (ev.chain === 'DTRYX') return '굿즈패키지';
  const fromTitle = GC.goodsFromTitle(ev.title);
  const nm = g && g.name ? GC.goodsFromTitle(g.name + ' 증정') || g.name.replace(/^[<\[][^>\]]*[>\]]\s*/, '') : '';
  return (nm || fromTitle || ev.title).replace(/\s*[(（][^)）]*\d{1,2}\/\d{1,2}[^)）]*[)）]/g, '').slice(0, 30);
}
function stockFor(ev, goodsId, th) {
  const list = (ev.stock || []).filter((s) => (!goodsId || s.goodsId === goodsId));
  const s = list.find((x) => x.theaterId && x.theaterId === th.id) || list.find((x) => x.theater.replace(/^(CGV|메가박스|롯데시네마)\s*/, '') === th.name);
  if (s) return { level: s.level, count: s.count, raw: s.raw };
  if (ev.allOut) return { level: 'out' };
  return { level: 'unknown' };
}

function createStPanel(evs, mode) {
  const el = document.createElement('div');
  el.className = 'sect stpanel';
  const dates = stDates(evs);
  const st = { el, evIds: evs.map((e) => e.id), mode, dates, date: dates[0] || null, onlyStock: true, showPast: false, token: 0, rows: [], done: 0, total: 0, errors: [], noShow: [], theaters: [] };
  el.addEventListener('click', (e) => {
    const b = e.target.closest('[data-stdate]'); if (b) { st.date = b.dataset.stdate; loadSt(st); return; }
    if (e.target.closest('[data-st-reload]')) loadSt(st, true);
  });
  el.addEventListener('change', (e) => {
    if (e.target.matches('[data-st-stock]')) { st.onlyStock = e.target.checked; loadSt(st); }
    if (e.target.matches('[data-st-past]')) { st.showPast = e.target.checked; drawSt(st); }
  });
  ST.cur = st;
  if (st.date) loadSt(st); else drawSt(st);
  return el;
}
function attachStPanel() { const slot = $('#stSlot'); if (slot && S.stPanel) slot.replaceWith(S.stPanel); }

async function loadSt(st, fresh) {
  const token = ++st.token;
  st.rows = []; st.done = 0; st.errors = []; st.noShow = []; st.unknownSites = false;
  const date = st.date;
  const evs = st.evIds.map((id) => S.events[id]).filter(Boolean).filter((ev) => activeOn(ev, date) || (ev.openEnd && ev.start <= date));
  // 지점별로 묶기: 같은 지점 시간표는 한 번만 요청
  const map = new Map();
  for (const ev of evs) {
    for (const th of GC.eventTheaters(ev)) {
      if (!th.known) st.unknownSites = true;
      if (st.onlyStock && th.level === 'out') continue;
      const k = th.chain + '|' + th.id;
      const m = map.get(k) || { th, refs: [] };
      m.refs.push({ evId: ev.id, goodsId: th.goodsId || null });
      map.set(k, m);
    }
  }
  st.theaters = [...map.values()];
  st.total = st.theaters.length;
  drawSt(st);
  await Promise.all(st.theaters.map(async ({ th, refs }) => {
    let res;
    try { res = await chrome.runtime.sendMessage({ type: 'schedule', chain: th.chain, theater: { id: th.id, name: th.name, brand: th.brand }, date, fresh: !!fresh }); }
    catch (e) { res = { ok: false, reason: String(e) }; }
    if (token !== st.token) return;
    st.done++;
    if (!res || !res.ok) { st.errors.push(`${SCHAIN[th.chain] || th.chain} ${th.name}: ${(res && res.reason) || '실패'}`); drawSt(st); return; }
    let hit = 0;
    for (const row of res.rows) {
      const goods = [];
      for (const r of refs) {
        const ev = S.events[r.evId]; if (!ev) continue;
        if (!GC.rowMatchesEvent(row, ev)) continue;
        if (!goods.find((g) => g.evId === r.evId && g.goodsId === r.goodsId)) goods.push(r);
      }
      if (goods.length) { st.rows.push({ row, th, goods }); hit++; }
    }
    if (!hit) st.noShow.push(`${SCHAIN[th.chain] || ''} ${th.name}`.trim());
    drawSt(st);
  }));
}

function drawSt(st) {
  const el = st.el; const t = today();
  const nowHM = nowCmpFor(st.date) || '';
  const isToday = !!nowCmpFor(st.date);
  const rows = st.rows.slice().sort((a, b) => a.row.start.localeCompare(b.row.start) || a.th.name.localeCompare(b.th.name, 'ko'));
  const past = isToday ? rows.filter((r) => r.row.start < nowHM) : [];
  const shown = st.showPast ? rows : rows.filter((r) => !(isToday && r.row.start < nowHM));
  const theatersWithRows = new Set(shown.map((r) => r.th.chain + r.th.id)).size;
  const loading = st.done < st.total;
  const next = shown.find((r) => !(isToday && r.row.start < nowHM) && (r.row.remain == null || r.row.remain > 0));
  let h = `<h4>🕒 굿즈 받을 수 있는 상영 시간 <span class="muted" style="font-weight:400">(시간순 · ${st.mode === 'movie' ? '이 영화의 모든 굿즈 이벤트' : '이 이벤트'})</span></h4>`;
  if (!st.dates.length) { el.innerHTML = h + `<div class="predict-box none">${window.GC_SITE ? '이 사이트는 오늘·내일 시간표만 보여줘요. 이 이벤트는 오늘·내일 진행일이 아니에요.' : '이벤트 기간이 끝났거나 2주 이후라 시간표가 아직 없어요.'}</div>`; return; }
  h += `<div class="stdates">${st.dates.map((d) => { const x = parseYmd(d); const rel = d === t ? '오늘' : d === addDays(t, 1) ? '내일' : d === addDays(t, -1) ? '심야' : WD[x.getDay()]; return `<button class="chip ${d === st.date ? 'on' : ''}" data-stdate="${d}">${x.getMonth() + 1}/${x.getDate()} <small>${rel}</small></button>`; }).join('')}</div>`;
  h += `<div class="sttools"><label class="tg"><input type="checkbox" data-st-stock ${st.onlyStock ? 'checked' : ''}> 굿즈 소진된 지점 빼기</label>
    ${isToday ? `<label class="tg"><input type="checkbox" data-st-past ${st.showPast ? 'checked' : ''}> 지난 회차 보기${past.length ? ` (${past.length})` : ''}</label>` : ''}
    ${window.GC_SITE ? '' : '<button class="btn small" data-st-reload>시간표 새로고침</button>'}
    <span class="muted">${loading ? `시간표 불러오는 중 ${st.done}/${st.total}곳…` : `서울 ${theatersWithRows}곳 · ${shown.length}회차`}</span></div>`;
  if (next && !loading) h += `<div class="stnext">다음으로 받을 수 있는 회차: <b>${esc(next.row.start)}</b> ${esc(next.th.name)} ${esc(next.row.hall)}</div>`;
  if (st.unknownSites) h += `<div class="hint">※ 이 영화관은 지점별 배부처를 공개하지 않아 서울 해당 지점 시간표를 모두 보여줘요. 배부 지점·조건은 공식 공지로 확인하세요.</div>`;
  if (st.date === addDays(t, -1)) h += `<div class="hint">※ 지금은 새벽이라 영화관 기준 '어제 영업일'의 심야 회차(24시 이후 표기)를 보여줘요.</div>`;
  else if (!isToday) h += `<div class="hint">※ 굿즈 재고 표시는 '지금' 기준이에요. ${md(st.date)}에는 달라질 수 있어요.</div>`;
  if (shown.length) {
    h += '<div class="stlist">' + shown.map(({ row, th, goods }) => {
      const pastRow = isToday && row.start < nowHM;
      const sold = row.remain === 0;
      const chips = goods.map((g) => {
        const ev = S.events[g.evId]; if (!ev) return '';
        const sk = stockFor(ev, g.goodsId, th);
        const cnt = sk.count != null ? ` ${sk.count}개` : '';
        const lab = st.mode === 'movie' ? `<span class="glabel">${esc(goodsLabel(ev, g.goodsId))}</span>` : (goods.length > 1 ? `<span class="glabel">${esc(goodsLabel(ev, g.goodsId))}</span>` : '');
        const stockTxt = sk.level === 'unknown' ? '<span class="muted">재고 미공개</span>' : `${lvChip(sk.level, sk.raw)}${cnt}`;
        return `<span class="gchip" data-open="${esc(ev.id)}" title="${esc(ev.title)}">${lab}${stockTxt}</span>`;
      }).join('');
      const seat = row.remain != null && row.total ? `${sold ? '<b class="soldtxt">매진</b>' : `잔여 ${row.remain}`}<small>/${row.total}</small>` : '';
      const tag = [row.pkg ? '<span class="tbadge pkg">굿즈패키지</span>' : '', row.special && !row.pkg ? `<span class="tbadge">${esc(row.special)}</span>` : ''].join('');
      return `<div class="strow ${pastRow ? 'past' : ''} ${sold ? 'sold' : ''}">
        <div class="st-time"><b>${esc(row.start)}</b><small>~${esc(row.end || '')}</small></div>
        <div class="st-where"><div><span class="badge" style="background:var(--${th.chain === 'DTRYX' ? 'DTRYX' : th.chain})">${esc(SCHAIN[th.chain] || th.chain)}</span> <b>${esc(th.name)}</b> ${tag}</div><small>${esc([row.hall, row.format].filter(Boolean).join(' · '))}</small></div>
        <div class="st-seat">${seat}</div>
        <div class="st-goods">${chips}</div>
        <a class="btn small" href="${esc(row.url || '#')}" target="_blank" rel="noopener">예매 ↗</a>
      </div>`;
    }).join('') + '</div>';
  } else if (!loading) {
    h += `<div class="predict-box none">${st.total ? `${md(st.date)}에 굿즈 대상 지점에서 이 영화 상영이 없거나, 아직 시간표가 열리지 않았어요.` : '이 날 굿즈를 받을 수 있는 지점이 없어요(모두 소진됐거나 배부 전).'}${past.length && !st.showPast ? ` 지난 회차 ${past.length}개는 숨겨져 있어요.` : ''}</div>`;
  }
  if (!loading && st.noShow.length) h += `<div class="hint">이 날 상영 없음: ${esc(st.noShow.join(', '))}</div>`;
  if (st.errors.length) h += `<div class="hint err">시간표를 못 불러온 곳: ${esc(st.errors.slice(0, 4).join(' / '))}${st.errors.length > 4 ? ` 외 ${st.errors.length - 4}곳` : ''}</div>`;
  el.innerHTML = h;
}

