// ───────── 상단 상태 ─────────
function renderSources() {
  const order = Object.keys(CHAINS);
  const now = Date.now();
  $('#sources').innerHTML = order.map((k) => {
    const m = S.meta[k] || {};
    let cls = 'stale', txt = '대기';
    if (m.running) { cls = 'run'; txt = '갱신 중'; }
    else if (m.backoffUntil && now < m.backoffUntil) { cls = 'err'; txt = `요청 제한 · ${Math.ceil((m.backoffUntil - now) / 60000)}분 뒤 재시도`; }
    else if (m.lastError && (!m.lastOk || m.lastErrorAt > m.lastOk)) { cls = 'err'; txt = '오류 · ' + m.lastError.slice(0, 30); }
    else if (m.lastOk) { cls = now - m.lastOk < 40 * 60000 ? 'ok' : 'stale'; txt = `${ago(m.lastOk)} · ${m.count ?? 0}건${m.via ? ' · ' + m.via : ''}`; }
    return `<span class="src ${cls}" title="${esc(m.lastError || '')}"><i></i>${CHAINS[k]} ${esc(txt)}</span>`;
  }).join('');
  $('#lastUpdated').textContent = S.lastRefresh ? `마지막 갱신 ${ago(S.lastRefresh)}` : '데이터 수집 중…';
}

function renderFilters() {
  $('#chainChips').innerHTML = Object.entries(CHAINS).map(([k, n]) => `<button class="chip ${S.chains.has(k) ? 'on' : ''}" data-chain="${k}"><i class="dot" style="background:var(--${k})"></i>${n}</button>`).join('');
  $('#typeChips').innerHTML = TYPES.map((t) => `<button class="chip ${S.types.has(t) ? 'on' : ''}" data-type="${esc(t)}">${esc(t)}</button>`).join('');
}

function render() {
