async function openSettings() {
  const { settings } = await chrome.storage.local.get('settings');
  const st = Object.assign({ enabled: {}, intervals: {}, indieSources: GC.INDIE_DEFAULTS, notify: true }, settings || {});
  const def = { LOTTE: 5, MEGABOX: 5, CGV: 15, CINEQ: 30, CINECUBE: 30, DTRYX: 60, INDIE: 60 };
  $('#srcSettings').innerHTML = Object.entries(CHAINS).map(([k, n]) => `<label><input type="checkbox" data-en="${k}" ${st.enabled[k] !== false ? 'checked' : ''}> ${n} <input type="number" min="${k === 'CGV' ? 10 : 3}" max="240" data-iv="${k}" value="${st.intervals[k] || def[k]}"></label>`).join('');
  const drawIndie = () => {
    $('#indieList').innerHTML = (st.indieSources || []).map((s, i) => `<div class="indie-row"><b>${esc(s.name)}</b><span class="url">${esc(s.url)}</span><button type="button" class="btn small" data-del="${i}">삭제</button></div>`).join('') || '<p class="hint">등록된 게시판이 없어요.</p>';
    $('#indieList').querySelectorAll('[data-del]').forEach((b) => b.onclick = () => { st.indieSources.splice(+b.dataset.del, 1); drawIndie(); save(); });
  };
  drawIndie();
  $('#notifyOn').checked = st.notify !== false;
  const meta = S.meta;
  $('#diag').innerHTML = `<table class="diag"><tr><th>소스</th><th>최근 성공</th><th>건수</th><th>방식</th><th>상태</th></tr>${Object.entries(CHAINS).map(([k, n]) => {
    const m = meta[k] || {};
    const errs = (m.errors || []).length ? `<div class="err">부분 오류 ${m.errors.length}건: ${esc(m.errors[0])}</div>` : '';
    return `<tr><td>${n}</td><td>${m.lastOk ? new Date(m.lastOk).toLocaleString('ko-KR') : '—'}</td><td>${m.count ?? '—'}</td><td>${m.mode === 'tab' ? '사이트 탭 경유' : '직접'}</td><td>${m.lastError ? `<span class="err">${esc(m.lastError)}</span>` : '정상'}${errs}</td></tr>`;
  }).join('')}</table>
  <p class="hint">학습된 데이터: ${Object.entries(S.learn).filter(([k]) => k !== '_done').map(([k, v]) => `${CHAINS[k] || k} 단계→소진 ${Object.values(v.levelToOut || {}).reduce((a, b) => a + b.length, 0)}건`).join(' · ') || '아직 없음 (굿즈가 소진되는 것을 관측하면 쌓여요)'} · 재고 이력 ${Object.keys(S.history).length.toLocaleString()}개 지점·굿즈</p>`;
  async function save() {
    st.enabled = {}; st.intervals = {};
    $('#srcSettings').querySelectorAll('[data-en]').forEach((c) => st.enabled[c.dataset.en] = c.checked);
    $('#srcSettings').querySelectorAll('[data-iv]').forEach((c) => st.intervals[c.dataset.iv] = Math.max(+c.min, +c.value || def[c.dataset.iv]));
    st.notify = $('#notifyOn').checked;
    await chrome.storage.local.set({ settings: st });
  }
  $('#srcSettings').onchange = save; $('#notifyOn').onchange = save;
  $('#indieAdd').onclick = async () => {
    const name = $('#indieName').value.trim(); let url = $('#indieUrl').value.trim();
    if (!name || !/^https?:\/\//.test(url)) { alertBox('극장 이름과 http(s) 주소를 입력하세요.'); return; }
    const origin = new URL(url).origin + '/*';
    const ok = await chrome.permissions.request({ origins: [origin] }).catch(() => false);
    if (!ok) { alertBox('해당 사이트 접근 권한이 필요해요.'); return; }
    st.indieSources = st.indieSources || [];
    st.indieSources.push({ key: 'u' + Date.now(), name, theater: name, url, base: url.replace(/\/$/, ''), parser: 'auto' });
    $('#indieName').value = ''; $('#indieUrl').value = '';
    drawIndie(); await save(); chrome.runtime.sendMessage({ type: 'refresh', force: true, only: ['INDIE'] });
  };
  $('#clearBackoff').onclick = () => chrome.runtime.sendMessage({ type: 'clearBackoff' });
  $('#resetData').onclick = async () => {
    if (!$('#resetData').dataset.confirm) { $('#resetData').dataset.confirm = 1; $('#resetData').textContent = '한 번 더 누르면 초기화'; return; }
    await chrome.storage.local.remove(['events', 'history', 'learn', 'meta', 'adapterCache', 'fetchMode']);
    $('#resetData').textContent = '초기화됨'; chrome.runtime.sendMessage({ type: 'refresh', force: true });
  };
  $('#settings').showModal();
  $('#settings').addEventListener('close', () => chrome.runtime.sendMessage({ type: 'settingsChanged' }), { once: true });
}
