setInterval(() => { if (today() !== lastDay) { if (S.sel === lastDay) S.sel = today(); lastDay = today(); load(); } }, 60000);

(function init() {
  const d = new Date(); S.month = [d.getFullYear(), d.getMonth()];
  const m = location.hash.match(/ev=([^&]+)/);
  const mm = location.hash.match(/movie=([^&]+)/);
  load().then(() => { if (m) openDrawer(decodeURIComponent(m[1])); else if (mm) openMovieDrawer(decodeURIComponent(mm[1])); });
  chrome.runtime.sendMessage({ type: 'refresh' }).catch(() => {});
})();

