/* 공개 사이트: 모바일 우선 레이아웃 */
html { -webkit-text-size-adjust: 100%; }
body { overscroll-behavior-y: none; }
.btn, .chip, .view-btn, .star { touch-action: manipulation; }

@media (max-width: 760px) {
  body { font-size: 14px; }
