  #search { flex: 1; width: auto; min-width: 0; font-size: 16px; padding: 8px 10px; }
  #refreshBtn { padding: 7px 10px; font-size: 13px; }
  .views { order: 2; }
  .view-btn { padding: 6px 12px; font-size: 13px; }

  .sources, .filters .chips { flex-wrap: nowrap; overflow-x: auto; -webkit-overflow-scrolling: touch; scrollbar-width: none; }
