  .src { flex: none; font-size: 11px; padding: 3px 8px; }
  .filters { padding: 8px 12px; gap: 6px 12px; }
  .filters .chips { width: 100%; }
  .chip { flex: none; padding: 6px 11px; }
  .tg { font-size: 12px; }

  .view-date { grid-template-columns: 1fr; gap: 12px; padding: 0 10px 16px; }
  .cal-wrap { position: static; padding: 10px; }
  .cal-head h2 { font-size: 16px; }
  .cal-grid { gap: 3px; }
  .day { min-height: 50px; padding: 4px; border-radius: 8px; }
  .day .num { width: 20px; height: 20px; font-size: 11px; }
  .day .cnt { font-size: 10px; }
  .day .dots .dot { width: 5px; height: 5px; }
