  .day .pill { bottom: 3px; right: 3px; }
  .legend { font-size: 10px; gap: 3px 8px; }

  .day-head h2 { font-size: 18px; }
  .day-head .meta { font-size: 12px; }
  .card { grid-template-columns: 4px 52px minmax(0, 1fr); gap: 10px; padding: 10px 10px 10px 0; position: relative; }
  .card .thumb { width: 52px; height: 52px; }
  .card .side { grid-column: 3; flex-direction: row; justify-content: flex-start; align-items: center; gap: 8px; }
  .card .star { position: absolute; top: 8px; right: 8px; }
  .card .title { font-size: 13.5px; padding-right: 22px; }
  .card .row1 { font-size: 10.5px; }
  .sbar { width: 80px; }

  .view-movie { padding: 0 10px 16px; }
  .mhead { flex-wrap: wrap; padding: 10px 12px; }
  .mhead .stbtn { margin-left: 0; width: 100%; padding: 8px; font-size: 13px; }
  .timeline { padding: 4px 10px 10px; }
  .axis, .trow { grid-template-columns: 112px 1fr; gap: 6px; }
  .trow .lbl { font-size: 11px; }
  .trow .lbl .badge { display: none; }
  .axis .ticks span { font-size: 9px; }

  .drawer { width: 100vw; }
  .drawer-inner { padding: calc(14px + env(safe-area-inset-top)) 14px calc(40px + env(safe-area-inset-bottom)); }
  .drawer .close { position: sticky; top: 0; float: right; z-index: 2; background: #fff; }
  .d-hero { grid-template-columns: 72px 1fr; gap: 10px; margin-right: 0; }
  .d-hero .thumb { width: 72px; height: 96px; }
  .d-title { font-size: 16px; }
  .d-actions .btn { flex: 1; text-align: center; }
  table.st { display: block; overflow-x: auto; white-space: nowrap; }

  .stpanel { padding: 10px; margin-left: -4px; margin-right: -4px; }
  .sttools { gap: 8px; }
  .strow { grid-template-columns: 52px minmax(0, 1fr) auto; grid-template-areas: "time where seat" "time goods book"; gap: 4px 8px; padding: 8px; }
  .st-time { grid-area: time; align-self: start; }
  .st-where { grid-area: where; }
  .st-seat { grid-area: seat; }
  .st-goods { grid-area: goods; flex-direction: row; flex-wrap: wrap; }
  .strow .btn.small { grid-area: book; align-self: end; padding: 5px 8px; }
  .gchip .glabel { max-width: 140px; }

  dialog { width: 96vw; }
  .foot { padding: 10px 12px calc(24px + env(safe-area-inset-bottom)); }
}
@media (max-width: 380px) {
  .day { min-height: 44px; }
  .day .cnt { display: none; }
}
@media (max-width: 760px) {
  .top { position: static; }
  .mhead { flex-wrap: wrap; }
  .mhead > div:nth-child(2) { flex: 1; min-width: 0; }
  .mhead .thumb { width: 40px; height: 40px; }
}

site/site.js.text:
/* 공개 사이트용: 확장 프로그램의 chrome.* 대신 data.json(15분마다 자동 갱신)을 읽는 읽기 전용 어댑터 */
window.GC_SITE = true;
(function () {
  let data = null;
  let loading = null;
  const listeners = [];
  const WATCH = 'gc_watch_v1';
  const readWatch = () => { try { return JSON.parse(localStorage.getItem(WATCH) || '{}'); } catch (e) { return {}; } };

  function loadData() {
    if (loading) return loading;
    loading = fetch('data.json?t=' + Date.now(), { cache: 'no-store' })
      .then((r) => { if (!r.ok) throw new Error('HTTP ' + r.status); return r.json(); })
      .then((d) => { data = d; window.GC_DATA = d; return d; })
      .catch((e) => { if (!data) { data = { events: {}, history: {}, learn: {}, meta: {}, showtimes: {}, dates: [], generatedAt: 0, loadError: String(e) }; window.GC_DATA = data; } return data; })
      .finally(() => { loading = null; });
    return loading;
  }
  const fire = () => listeners.forEach((f) => { try { f({ events: {} }, 'local'); } catch (e) {} });

  window.chrome = {
    storage: {
      local: {
        async get(keys) {
          if (!data) await loadData();
          const all = { events: data.events, history: data.history, learn: data.learn, meta: data.meta, lastRefresh: data.generatedAt, settings: null, watch: readWatch() };
          const ks = keys == null ? Object.keys(all) : Array.isArray(keys) ? keys : [keys];
          const o = {}; ks.forEach((k) => { o[k] = all[k]; }); return o;
        },
        async set(o) { if (o.watch) { try { localStorage.setItem(WATCH, JSON.stringify(o.watch)); } catch (e) {} fire(); } },
        async remove() {}
      },
      onChanged: { addListener: (f) => listeners.push(f) }
    },
    runtime: {
      getURL: (p) => p,
      async sendMessage(m) {
        if (m.type === 'refresh') { const old = data && data.generatedAt; await loadData(); if (data.generatedAt !== old) fire(); return { ok: true }; }
        if (m.type === 'schedule') {
          if (!data) await loadData();
          const k = `${m.chain}|${m.theater.id}|${m.date}`;
          const v = (data.showtimes || {})[k];
          if (!v) return { ok: false, reason: (data.dates || []).includes(m.date) ? '굿즈 소진 지점은 시간표를 모으지 않아요' : '오늘·내일 시간표만 제공' };
          if (v.error) return { ok: false, reason: v.error };
          return { ok: true, rows: v.map((r) => Object.assign({ chain: m.chain, theaterId: m.theater.id, date: m.date }, r)), cachedAt: data.generatedAt };
        }
        return { ok: true };
      }
    },
    permissions: { request: async () => false },
    tabs: { create: (o) => window.open(o.url, '_blank') }
  };
  // 창을 다시 볼 때·2분마다 새 데이터 확인
  setInterval(() => { if (!document.hidden) window.chrome.runtime.sendMessage({ type: 'refresh' }); }, 120000);
  document.addEventListener('visibilitychange', () => { if (!document.hidden) window.chrome.runtime.sendMessage({ type: 'refresh' }); });
})();
